      "path": "package.json",
      "content": "{\n  \"name\": \"@nagi-ovo/dsh-visualize\",\n  \"description\": \"DSH inline visualization plugin: a visualize tool + bundled skill let the model render interactive HTML fragments as sandboxed cards in the conversation (Codex /visualize semantics).\",\n  \"icon\": \"assets/icon.svg\",\n  \"version\": \"0.1.7\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"src\",\n    \"assets\",\n    \"cordis.patch.yml\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsdown\",\n    \"typecheck\": \"tsc -p tsconfig.json && tsc -p tsconfig.client.json\",\n    \"test\": \"vitest run\",\n    \"check\": \"pnpm run typecheck && pnpm run test && pnpm run build\",\n    \"prepublishOnly\": \"pnpm run build\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Nagi-ovo/dsh-visualize.git\"\n  },\n  \"homepage\": \"https://github.com/Nagi-ovo/dsh-visualize#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Nagi-ovo/dsh-visualize/issues\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\"\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-fs\": \"^0.1.0-rc.6 || ^0.2.0-rc.1 || ^0.2.1-0\",\n    \"@deepseek-ai/dsh-llm\": \"^0.1.0-rc.6 || ^0.2.0-rc.1 || ^0.2.1-0\",\n    \"@deepseek-ai/dsh-sandbox-policy\": \"^0.1.0-rc.6 || ^0.2.0-rc.1 || ^0.2.1-0\",\n    \"@deepseek-ai/dsh-session\": \"^0.1.0-rc.6 || ^0.2.0-rc.1 || ^0.2.1-0\",\n    \"@deepseek-ai/dsh-skill\": \"^0.1.0-rc.6 || ^0.2.0-rc.1 || ^0.2.1-0\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.0-rc.6 || ^0.2.0-rc.1 || ^0.2.1-0\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\",\n    \"react\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.4\",\n    \"@deepseek-ai/dsh-client-store\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-chat\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-tool\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-fs\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-sandbox-policy\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-skill\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/schemastery\": \"3.18.4\",\n    \"@types/node\": \"^22.0.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"^18.3.1\",\n    \"jsdom\": \"^25.0.1\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^5.9.3\",\n    \"vitest\": \"^4.1.1\"\n  },\n  \"license\": \"BSD-3-Clause\"\n}\n"
    },
    {
      "path": "src/client/StreamingPreview.tsx",
      "content": "/**\n * Live streaming preview docked under the composer: while the model is still\n * generating a `visualize` call, the accumulated argument stream is parsed for\n * the fragment prefix and rendered into the same sandboxed frame the settled\n * card uses — complete scripts run, a still-open trailing script is held back\n * until its closing tag streams in (a half-streamed script body is almost\n * never valid JavaScript). Renders nothing when no `visualize` call is\n * streaming; once the call settles the preview unmounts and the transcript\n * card takes over.\n *\n * Source: from dsh 0.1.2 the session snapshot no longer carries the streaming\n * partial, and the host's own projections of the argument stream differ per\n * release (0.1.7 folds it into Assistant blocks that publish nothing for a\n * text-less step; 0.2.1 keeps it in the Tool node's lazy argument view). The\n * one shape stable across releases is the transient `assistant/live-chunk`\n * event itself, so a state-only Conversation Definition folds its\n * `tool-call-delta` chunks into Turn data, and the dock entry reads the open\n * Turn's value through the session-standard Chat selector. dsh 0.1.1 still\n * has the snapshot partial and no registry, and keeps reading it.\n */\n\nimport {\n  useEffect, useMemo, useRef, useState, useSyncExternalStore, type CSSProperties,\n} from 'react'\nimport type { PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'\nimport type {\n  ConversationLocationData, ConversationLocationDataSource, ConversationNodeDefinition,\n  ConversationTimelineSnapshot,\n} from '@deepseek-ai/dsh-client-ui-conversation/client'\n// Type-only: pulls the `conversation.input.dock` SlotMap declaration.\nimport type {} from '@deepseek-ai/dsh-client-ui-conversation/client'\n// Type-only: pulls the session-standard `useChat` selector declaration.\nimport type {} from '@deepseek-ai/dsh-client-ui-chat/client'\nimport { extractStreamingFragment, trimStreamingScripts, VISUALIZE_TOOL_NAME } from '../fragment.ts'\nimport { buildStreamShellDoc, HEIGHT_MESSAGE_TYPE, STREAM_MESSAGE_TYPE } from '../shell.ts'\nimport { resolveTheme } from './theme.ts'\nimport { liveStyle } from './style.ts'\n\n/** Definition kind and Turn data key; namespaced by package to stay unique. */\nexport const STREAM_KEY = 'dsh-visualize-stream'\n\n/** The `visualize` call still streaming in a Turn. */\nexport interface VisualizeStreamData {\n  readonly callId: string\n  readonly argsRaw: string\n}\n\ndeclare module '@deepseek-ai/dsh-client-ui-conversation/client' {\n  interface ConversationTurnDataMap {\n    /** The Turn's still-streaming `visualize` call, absent when none streams. */\n    'dsh-visualize-stream': VisualizeStreamData\n  }\n}\n\n/** One streamed tool-call block, addressed by its step and content index. */\ninterface StreamedCall {\n  readonly slot: string\n  readonly callId: string\n  readonly name: string\n  readonly argsRaw: string\n}\n\ninterface StreamState {\n  readonly turn: number\n  /** Unsettled calls in stream order. */\n  readonly calls: readonly StreamedCall[]\n}\n\n/** One argument chunk, already checked: `final` marks a settled block's full text. */\ninterface CallChunk {\n  readonly step: number\n  readonly index: number\n  readonly id: string\n  readonly name: string | undefined\n  readonly text: string\n  readonly final: boolean\n}\n\n/** What one accepted event means to the fold. */\ntype StreamInput =\n  | { readonly kind: 'turn'; readonly turn: number }\n  | { readonly kind: 'chunk'; readonly turn: number; readonly chunk: CallChunk }\n  | { readonly kind: 'call'; readonly turn: number; readonly callId: string }\n\nconst isIndex = (value: unknown): value is number => Number.isSafeInteger(value) && (value as number) >= 0\nconst isRecord = (value: unknown): value is Record<string, unknown> => typeof value === 'object' && value !== null\nconst idOf = (value: unknown): string => typeof value === 'string' || typeof value === 'number' ? String(value) : ''\n\n/**\n * Read an argument chunk (dsh-llm `StreamChunk`): a `tool-call-delta`, or the\n * `block-end` of a tool-call block.\n * @param chunk - the live chunk, unchecked.\n * @param step - the chunk's step.\n * @returns the checked chunk, or undefined for anything else or malformed.\n */\nfunction callChunk(chunk: unknown, step: number): CallChunk | undefined {\n  if (!isRecord(chunk) || !isIndex(chunk.index)) return undefined\n  if (chunk.type === 'tool-call-delta') {\n    return {\n      step, index: chunk.index, id: idOf(chunk.id),\n      name: typeof chunk.name === 'string' ? chunk.name : undefined,\n      text: typeof chunk.argumentsDelta === 'string' ? chunk.argumentsDelta : '',\n      final: false,\n    }\n  }\n  const block = chunk.block\n  if (chunk.type !== 'block-end' || !isRecord(block) || block.type !== 'tool-call') return undefined\n  if (typeof block.arguments !== 'string') return undefined\n  return {\n    step, index: chunk.index, id: idOf(block.id),\n    name: typeof block.name === 'string' ? block.name : undefined,\n    text: block.arguments,\n    final: true,\n  }\n}\n\n/**\n * Classify an event without trusting its payload: a history window can begin\n * anywhere and a host may change shapes, and a throw here would abort the\n * host's whole conversation assembly, not just this preview.\n * @param event - any Session event the engine offers.\n * @returns the fold input, or undefined when unrelated or malformed.\n */\nfunction streamInput(event: { readonly type: string; readonly data?: unknown }): StreamInput | undefined {\n  const data = event.data\n  if (!isRecord(data) || !isIndex(data.turn)) return undefined\n  const turn = data.turn\n  if (event.type === 'turn/start') return { kind: 'turn', turn }\n  if (event.type === 'tool/call') return { kind: 'call', turn, callId: idOf(data.callId) }\n  if (event.type !== 'assistant/live-chunk' || !isIndex(data.step)) return undefined\n  const chunk = callChunk(data.chunk, data.step)\n  return chunk === undefined ? undefined : { kind: 'chunk', turn, chunk }\n}\n\n/**\n * Fold one argument chunk. Later deltas of a call may omit its name and id,\n * so a call is addressed by step and content index, the way the provider\n * stream addresses it; a settled block replaces the accumulated text with\n * the authoritative arguments.\n * @param calls - calls so far.\n * @param chunk - the checked chunk.\n * @returns the next call list.\n */\nfunction foldChunk(calls: readonly StreamedCall[], chunk: CallChunk): readonly StreamedCall[] {\n  const slot = `${chunk.step}:${chunk.index}`\n  const at = calls.findIndex(call => call.slot === slot)\n  const previous = at === -1 ? undefined : calls[at]\n  const next: StreamedCall = {\n    slot,\n    callId: previous?.callId || chunk.id,\n    name: chunk.name ?? previous?.name ?? '',\n    argsRaw: chunk.final ? chunk.text : (previous?.argsRaw ?? '') + chunk.text,\n  }\n  return at === -1 ? [...calls, next] : calls.map((call, index) => index === at ? next : call)\n}\n\n/**\n * Apply one event. Total: unrelated or malformed input returns the state.\n * @param state - state so far.\n * @param event - the matched event.\n * @returns the next state.\n */\nfunction reduceStream(state: StreamState, event: { readonly type: string; readonly data?: unknown }): StreamState {\n  const input = streamInput(event)\n  if (input?.kind === 'chunk') return { ...state, calls: foldChunk(state.calls, input.chunk) }\n  if (input?.kind !== 'call') return state\n  const calls = state.calls.filter(call => call.callId !== input.callId)\n  return calls.length === state.calls.length ? state : { ...state, calls }\n}\n\n/**\n * Turn-local fold of the argument stream; it publishes Turn data and no view\n * Node. Live chunks are transient: when the Assistant message settles the\n * engine retires them and replays the Context without them, which empties the\n * value on its own; a durable `tool/call` also settles its call.\n *\n * Every accepted event is a start candidate. The engine rejects a start that\n * arrives on a Context already holding matches, and a history window can\n * begin at any event of a turn (a long turn loses its `turn/start`, keeps a\n * `tool/call`, and then streams again), so no event may be an update-only\n * match; the earliest loaded one opens the Context and the rest fold.\n */\nexport const streamDefinition: ConversationNodeDefinition<StreamState> = {\n  kind: STREAM_KEY,\n  match: (event) => {\n    const input = streamInput(event)\n    return input === undefined ? null : { id: String(input.turn), role: 'start' }\n  },\n  start: (_context, match) => {\n    const input = streamInput(match.event)\n    return reduceStream({ turn: input?.turn ?? 0, calls: [] }, match.event)\n  },\n  update: (context, match) => reduceStream(context.state, match.event),\n  publication: match => match.event.type === 'assistant/live-chunk' ? 'animation-frame' : 'immediate',\n  buildLocationData: (context, scope, previous) => {\n    if (scope !== 'turn' || context.state === undefined) return null\n    const { turn, calls } = context.state\n    // Last matching call: a turn can contain several visualize calls; only the\n    // most recent one can still be streaming.\n    let call: StreamedCall | undefined\n    for (const candidate of calls) if (candidate.name === VISUALIZE_TOOL_NAME) call = candidate\n    if (call === undefined) return null\n    if (previous?.kind === 'turn' && previous.turn === turn && previous.key === STREAM_KEY\n      && previous.value.callId === call.callId && previous.value.argsRaw === call.argsRaw) return previous\n    return {\n      kind: 'turn', turn, key: STREAM_KEY, value: { callId: call.callId, argsRaw: call.argsRaw },\n    } satisfies ConversationLocationData\n  },\n}\n\n/** Dock entry props: the InputZone owner share (live conversation snapshot). */\ntype StreamingPreviewProps = PropsRuntime<'conversation.input.dock'>\n\n/**\n * Flush interval for posting fragment updates into the persistent shell.\n * Updates are incremental DOM syncs, not reloads, so this can run near\n * per-delta speed; 150ms keeps the reveal continuous at negligible cost.\n */\nconst FLUSH_MS = 150\n\n/**\n * Preview height ceiling. The frame tracks the shell's *measured* content\n * height (its height reports), so invisible early markup — style blocks,\n * empty containers — keeps the frame collapsed and painted components grow\n * it; the cap stops a tall fragment from crowding out the composer. Reserving\n * space no paint has claimed reads as a layout bug, not as anticipation.\n */\nconst PREVIEW_MAX_HEIGHT = 300\n\n/**\n * The input dock spans the conversation view, not the composer column, so the\n * preview constrains itself to the composer's width family and centers.\n */\nconst wrapStyle: CSSProperties = { margin: '6px auto 2px', maxWidth: 760, width: '100%' }\n\nconst labelStyle: CSSProperties = {\n  fontSize: 12,\n  opacity: 0.65,\n  margin: '0 0 4px',\n}\n\nconst frameStyle: CSSProperties = {\n  display: 'block',\n  width: '100%',\n  border: 0,\n  background: 'transparent',\n  transition: 'height 240ms ease',\n}\n\n/**\n * Throttle a fast-changing string: re-emits at most every {@link FLUSH_MS},\n * with a trailing flush so the final value always lands. A plain trailing\n * debounce would starve under a continuous token stream — every delta would\n * reset the timer — so this flushes on the leading edge when the interval has\n * already elapsed.\n * @param value - the raw per-render value.\n * @returns the throttled value.\n */\nfunction useThrottled(value: string): string {\n  const [shown, setShown] = useState(value)\n  const lastFlush = useRef(0)\n  useEffect(() => {\n    const elapsed = Date.now() - lastFlush.current\n    if (elapsed >= FLUSH_MS) {\n      lastFlush.current = Date.now()\n      setShown(value)\n      return\n    }\n    const timer = setTimeout(() => {\n      lastFlush.current = Date.now()\n      setShown(value)\n    }, FLUSH_MS - elapsed)\n    return () => clearTimeout(timer)\n  }, [value])\n  return shown\n}\n\n/** The mounted preview, split out so hooks only run while a call streams. */\nfunction Preview({ argsRaw }: { argsRaw: string }) {\n  const throttled = useThrottled(argsRaw)\n  const fragment = extractStreamingFragment(throttled)\n  const preview = fragment === undefined ? '' : trimStreamingScripts(fragment)\n  const hasContent = preview.trim().length > 0\n  const frameRef = useRef<HTMLIFrameElement | null>(null)\n  const [loaded, setLoaded] = useState(false)\n  const [contentHeight, setContentHeight] = useState(0)\n  // Follow the shell's height reports so the frame hugs what is actually\n  // painted; the CSS transition turns each growth step into a smooth reveal.\n  useEffect(() => {\n    const onMessage = (event: MessageEvent) => {\n      const report = event.data as { type?: unknown; token?: unknown; height?: unknown } | null\n      if (report?.type !== HEIGHT_MESSAGE_TYPE || report.token !== 'streaming-preview') return\n      if (typeof report.height !== 'number' || !Number.isFinite(report.height)) return\n      setContentHeight(Math.max(0, Math.ceil(report.height)))\n    }\n    addEventListener('message', onMessage)\n    return () => removeEventListener('message', onMessage)\n  }, [])\n  // The shell loads ONCE per streaming call; updates flow over postMessage\n  // and sync incrementally, so unchanged components persist and new ones\n  // float in instead of the whole frame reloading per flush.\n  // The iframe takes the scheme baked into the shell: a mismatch makes the\n  // browser paint an opaque canvas behind the transparent preview.\n  const { doc, colorScheme } = useMemo(() => {\n    const theme = resolveTheme()\n    return {\n      doc: buildStreamShellDoc({ ...theme, reportToken: 'streaming-preview', style: liveStyle() }),\n      colorScheme: theme.colorScheme,\n    }\n  }, [])\n  useEffect(() => {\n    if (!loaded || !hasContent) return\n    frameRef.current?.contentWindow?.postMessage({\n      type: STREAM_MESSAGE_TYPE,\n      token: 'streaming-preview',\n      fragment: preview,\n    }, '*')\n  }, [loaded, hasContent, preview])\n  return (\n    <div style={wrapStyle}>\n      <div style={labelStyle}>\n        {hasContent ? 'Visualize · streaming preview' : 'Visualize · composing…'}\n      </div>\n      <iframe\n        ref={frameRef}\n        sandbox=\"allow-scripts\"\n        referrerPolicy=\"no-referrer\"\n        title=\"Visualization streaming preview\"\n        srcDoc={doc}\n        style={{ ...frameStyle, colorScheme, height: hasContent ? Math.min(contentHeight, PREVIEW_MAX_HEIGHT) : 0 }}\n        onLoad={() => setLoaded(true)}\n      />\n    </div>\n  )\n}\n\n/** The open Turn's stream source, or undefined when the host has none. */\ntype StreamSource = ConversationLocationDataSource<Readonly<VisualizeStreamData> | undefined>\n\nconst NO_SOURCE: StreamSource = { getSnapshot: () => undefined, subscribe: () => () => undefined }\n\n/**\n * The latest Turn's stream source. A Location's data store is observable on\n * its own, so the Chat selector only tracks which Turn is latest and every\n * argument delta reaches the preview without re-reading the Chat snapshot.\n * @param timeline - the Chat target's Turn/Step facts; older hosts may omit it.\n * @returns the source, or undefined before any Turn or without a data store.\n */\nexport function latestStreamSource(timeline: ConversationTimelineSnapshot | undefined): StreamSource | undefined {\n  const turn = timeline?.turnOrder.at(-1)\n  const location = turn === undefined ? undefined : timeline?.turns.get(turn)\n  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- feature-detect the data store\n  return typeof location?.data?.source === 'function' ? location.data.source(STREAM_KEY) : undefined\n}\n\n/** Dock body on hosts with the Conversation registry (dsh 0.1.2+). */\nfunction TurnStream({ useChat }: { useChat: StreamingPreviewProps['useChat'] }) {\n  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- a host may publish no Chat snapshot yet\n  const source = useChat(snapshot => latestStreamSource(snapshot?.timeline)) ?? NO_SOURCE\n  const stream = useSyncExternalStore(source.subscribe, source.getSnapshot)\n  if (stream === undefined) return null\n  // Keyed by call: a second visualize call in the same turn gets a fresh shell.\n  return <Preview key={stream.callId} argsRaw={stream.argsRaw} />\n}\n\n/** The slice of a dsh 0.1.1 session snapshot the legacy path reads. */\ninterface LegacyPartial {\n  readonly partial?: { readonly blocks?: readonly { kind?: string; name?: string; argsRaw?: string }[] } | null\n}\n\n/**\n * Dock entry: mounts the preview exactly while a `visualize` call streams.\n */\nexport function StreamingPreview({ session, useChat }: StreamingPreviewProps) {\n  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- absent on dsh 0.1.1\n  if (typeof useChat === 'function') return <TurnStream useChat={useChat} />\n  // dsh 0.1.1: the streaming partial still rides on the session snapshot.\n  // Defensive guard mirroring the official dock rows: a host passing no\n  // session must degrade to an empty dock instead of crashing.\n  const blocks = (session as LegacyPartial | undefined)?.partial?.blocks\n  if (blocks === undefined) return null\n  let argsRaw: string | undefined\n  for (const block of blocks) {\n    if (block.kind === 'tool-call' && block.name === VISUALIZE_TOOL_NAME) argsRaw = block.argsRaw\n  }\n  if (argsRaw === undefined) return null\n  return <Preview argsRaw={argsRaw} />\n}\n"
    },
    {
      "path": "src/client/VisualizeCard.tsx",
      "content": "/**\n * The `visualize` toolview: renders the persisted fragment from the call's\n * durable meta inside `<iframe sandbox=\"allow-scripts\">` with the frame's own\n * CSP. Replay-stable by construction — everything drawn derives from the\n * logged call slice, never from the fragment file.\n *\n * Theme bridge: the card resolves the host's `--dsw-alias-*` design tokens\n * (whale-blue brand accent included) at render time and injects them into the\n * frame document as `--dsh-viz-*` variables; a mutation of the root element's\n * attributes or an OS appearance flip re-resolves them, so the frame follows\n * live theme switches. The frame body stays transparent to blend with the\n * conversation surface.\n *\n * Height: a sandboxed frame's document is unreachable from the parent, so the\n * frame posts its scroll height (tagged with this call's id) and the card\n * sizes the iframe, capped per mode with internal scrolling past the cap.\n *\n * Open in new window: the header's icon button reopens the same frame\n * document full-size in its own tab, wrapped in a script-free page whose only\n * content is the identically sandboxed iframe (see window-doc.ts).\n *\n * Page mode: a `page` card is built for a whole browser tab, so the chat shows\n * a launcher instead — title, summary, a live but inert thumbnail of the page\n * laid out at desktop width and scaled into the card, and a button that opens\n * the page through the same script-free wrapper. A secondary toggle shows the\n * page in the conversation, for browsers or hosts that will not open a tab.\n *\n * Images: a card whose meta lists `data-viz-src` images waits for their\n * bytes from the plugin's image route and renders them as data URLs under\n * the unchanged frame CSP (images.ts); one that fails keeps its placeholder.\n *\n * Prompts: where the registration injects a {@link PromptSink}, an in-chat\n * frame's `dshViz.prompt(text)` lands in the composer as a draft, behind the\n * parent-side gates in prompt-bridge.ts. New-window tabs and thumbnails never\n * relay prompts.\n *\n * State: a settled in-chat frame's `dshViz.state` and `data-viz-keep`\n * changes are stored per card (card-state.ts) and baked into the next\n * document built for that card, so a reload, a reopened session or a patch\n * starts where the reader left it. Thumbnails and new-window tabs start from\n * the saved state but save nothing; the streaming preview has none.\n */\n\nimport { useEffect, useMemo, useRef, useState, type CSSProperties, type RefObject } from 'react'\nimport type { ToolCallViewProps } from '@deepseek-ai/dsh-client-ui-tool/client'\nimport { visualizeMetaFrom, visualizeMetaFromArgs, type VisualizeMeta } from '../fragment.ts'\nimport { buildFrameDoc, HEIGHT_MESSAGE_TYPE, type FrameVariant } from '../shell.ts'\nimport { PROMPT_INTERVAL_MS, readerIsInFrame, readPromptMessage, type PromptSink } from './prompt-bridge.ts'\nimport { buildWindowDoc, FRAME_SANDBOX } from '../window-doc.ts'\nimport { resolveTheme } from './theme.ts'\nimport { liveStyle, noteSettledStyle } from './style.ts'\nimport { useCardImages } from './images.ts'\nimport { cardStateKey, cardStates, readStateMessage } from './card-state.ts'\n\n/** Iframe height bounds; content beyond the cap scrolls inside the frame. */\nconst MIN_HEIGHT = 48\nconst HEIGHT_CAP: Record<VisualizeMeta['mode'], number> = { inline: 800, wide: 1200, page: 800 }\n\nconst headerStyle: CSSProperties = {\n  display: 'flex',\n  alignItems: 'baseline',\n  gap: 8,\n  fontSize: 12,\n  opacity: 0.65,\n  margin: '2px 0 6px',\n  overflow: 'hidden',\n  whiteSpace: 'nowrap',\n}\n\n/**\n * The card never widens its column: `minWidth: 0` lets the card shrink as a\n * flex or grid item (whose automatic minimum is its min-content width, here\n * the whole no-wrap header), so a long path truncates instead of stretching\n * the frame past the transcript.\n */\nconst cardStyle: CSSProperties = { minWidth: 0, maxWidth: '100%' }\n\n/** Title keeps its width until it alone fills the row; the path yields first. */\nconst titleStyle: CSSProperties = {\n  fontWeight: 500,\n  flexShrink: 0,\n  maxWidth: '100%',\n  overflow: 'hidden',\n  textOverflow: 'ellipsis',\n}\n\nconst pathStyle: CSSProperties = { minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis' }\n\n/** Icon button at the header's end; it never yields width to the path. */\nconst openStyle: CSSProperties = {\n  alignSelf: 'center',\n  display: 'inline-flex',\n  alignItems: 'center',\n  justifyContent: 'center',\n  flexShrink: 0,\n  marginLeft: 'auto',\n  width: 22,\n  height: 22,\n  padding: 0,\n  border: 0,\n  borderRadius: 4,\n  background: 'transparent',\n  color: 'inherit',\n  cursor: 'pointer',\n  // The header clips its overflow; keep the focus ring inside the button.\n  outlineOffset: -2,\n}\n\n/**\n * Open the card full-size in its own tab. The tab is a script-free Blob page\n * holding the same sandboxed frame (see window-doc.ts), themed as the host is\n * right now. Synchronous end to end so the browser treats it as a user-opened\n * tab rather than a blocked popup. The URL is not revoked: the tab can then be\n * reloaded, and the browser frees it when the chat page unloads.\n * @param meta - the card to open.\n * @param callId - correlation token base for the frame's height reports.\n * @param stateKey - the card's saved-state key; the tab starts from that\n *   state but, with no card behind it, saves nothing.\n */\nexport function openInWindow(meta: VisualizeMeta, callId: string, stateKey?: string): void {\n  const { themeVars, colorScheme } = resolveTheme()\n  const variant = variantOf(meta)\n  const frameDoc = buildFrameDoc({\n    fragment: meta.fragment,\n    title: meta.title,\n    themeVars,\n    colorScheme,\n    style: meta.style,\n    // Distinct from the in-chat token, so these reports never size a card.\n    reportToken: `window:${callId}`,\n    variant,\n    savedState: stateKey === undefined ? undefined : cardStates.read(stateKey),\n  })\n  const background = (variant === 'page' ? themeVars.page : themeVars.card) ?? ''\n  const page = buildWindowDoc({ frameDoc, title: meta.title, colorScheme, background, variant })\n  const url = URL.createObjectURL(new Blob([page], { type: 'text/html' }))\n  window.open(url, '_blank', 'noopener')\n}\n\n/**\n * Whether this browser can open a card in its own tab: an embedding host may\n * strip `window.open` or Blob URLs, and a page card then renders in place.\n * @returns true when both are available.\n */\nfunction canOpenWindow(): boolean {\n  return typeof window.open === 'function' && typeof URL.createObjectURL === 'function'\n}\n\n/** The frame variant a card's mode lays its document out for. */\nfunction variantOf(meta: VisualizeMeta): FrameVariant {\n  return meta.mode === 'page' ? 'page' : 'card'\n}\n\n/** Whether the host UI is in Chinese; the plugin ships no locale catalogue. */\nfunction hostIsZh(): boolean {\n  return document.documentElement.lang.toLowerCase().startsWith('zh')\n}\n\n/** Accessible name of the open control, in the host's language. */\nfunction openLabel(): string {\n  return hostIsZh() ? '在新窗口打开' : 'Open in new window'\n}\n\n/** Status line while a card's images load, in the host's language. */\nfunction loadingImagesLabel(): string {\n  return hostIsZh() ? '正在载入图片…' : 'loading images…'\n}\n\n/** Arrow-out-of-box glyph, sized to the 12px header text. */\nfunction OpenIcon() {\n  return (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.5\"\n      strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\">\n      <path d=\"M9.5 2.5h4v4\" />\n      <path d=\"M13.5 2.5 7.5 8.5\" />\n      <path d=\"M12 9.5v3a1 1 0 0 1-1 1H3.5a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1h3\" />\n    </svg>\n  )\n}\n\nconst frameStyle: CSSProperties = {\n  display: 'block',\n  width: '100%',\n  border: 0,\n  background: 'transparent',\n}\n\n/** First text line of the durable result content, for the error row. */\nfunction firstResultLine(content: readonly { type: string; text?: string }[]): string {\n  for (const block of content) {\n    if (block.type === 'text' && typeof block.text === 'string' && block.text.length > 0) {\n      const newline = block.text.indexOf('\\n')\n      return newline === -1 ? block.text : block.text.slice(0, newline)\n    }\n  }\n  return 'visualization failed'\n}\n\n/**\n * Re-render trigger for host theme switches: bumped whenever the host flips\n * appearance, so each frame document re-resolves the bridged palette.\n * @returns a counter that changes on every theme change.\n */\nexport function useThemeTick(): number {\n  const [themeTick, setThemeTick] = useState(0)\n  useEffect(() => {\n    const bump = () => setThemeTick(tick => tick + 1)\n    const observer = new MutationObserver(bump)\n    // Both mount points: DSH toggles dark via a body attribute, other hosts\n    // conventionally re-theme via root-element attributes.\n    observer.observe(document.documentElement, { attributes: true })\n    observer.observe(document.body, { attributes: true })\n    const media = matchMedia('(prefers-color-scheme: dark)')\n    media.addEventListener('change', bump)\n    return () => {\n      observer.disconnect()\n      media.removeEventListener('change', bump)\n    }\n  }, [])\n  return themeTick\n}\n\n/** One built frame document and the scheme baked into it. */\ninterface FrameDoc {\n  doc: string\n  /**\n   * The `color-scheme` the document's root declares. The iframe element must\n   * use the same one: where the two differ, the browser paints an opaque\n   * canvas behind the document instead of letting the card's transparent\n   * background show the chat surface (a near-black slab in dark mode).\n   * Chrome reads a sandboxed (out-of-process) frame's scheme when the element\n   * loads, and misses a change that lands together with a new `srcdoc`, so\n   * the frames key on it: a theme switch mounts a fresh iframe, which reloads\n   * just as the new `srcdoc` alone would.\n   */\n  colorScheme: 'light' | 'dark'\n}\n\n/** Which saved state a frame document starts from, and whether it saves changes. */\ninterface FrameStateUse {\n  key: string\n  saves: boolean\n}\n\n/**\n * The frame document for one card, rebuilt on theme changes.\n * @param meta - the card.\n * @param reportToken - height-report correlation token.\n * @param variant - surface the document lays out for.\n * @param promptable - whether the frame's `dshViz.prompt` is relayed.\n * @param state - the card's saved-state key, when it has one.\n * @returns the srcdoc string and its scheme, for the iframe's own `color-scheme`.\n */\nfunction useFrameDoc(\n  meta: VisualizeMeta, reportToken: string, variant: FrameVariant, promptable = false, state?: FrameStateUse,\n): FrameDoc {\n  const themeTick = useThemeTick()\n  // Re-resolved as often as before (each new meta, each theme tick); themeTick\n  // is the deliberate trigger for the palette read.\n  const theme = useMemo(() => resolveTheme(), [meta, themeTick])\n  const themeKey = JSON.stringify(theme)\n  const stateKey = state?.key\n  // Saved state is read only when the document changes for its own reasons\n  // (markup, title, style, surface, theme), never because the state did:\n  // otherwise every input the frame records would rebuild and reload it.\n  const savedState = useMemo(\n    () => stateKey === undefined ? undefined : cardStates.read(stateKey),\n    [stateKey, themeKey, meta.fragment, meta.title, meta.style, variant],\n  )\n  const savesState = state?.saves === true\n  return useMemo(() => {\n    const doc = buildFrameDoc({\n      fragment: meta.fragment, title: meta.title, themeVars: theme.themeVars, colorScheme: theme.colorScheme,\n      reportToken, variant, style: meta.style, promptable, savedState, savesState,\n    })\n    return { doc, colorScheme: theme.colorScheme }\n  }, [meta, reportToken, variant, promptable, theme, savedState, savesState])\n}\n\n/**\n * Store this frame's state snapshots under the card's key. As with prompts,\n * only messages from this very frame window count; the key is the card's,\n * never one the message names.\n * @param frameRef - the card's iframe.\n * @param token - the frame's correlation token.\n * @param stateKey - the card's saved-state key, or undefined when it saves nothing.\n */\nfunction useStateRelay(frameRef: RefObject<HTMLIFrameElement | null>, token: string, stateKey: string | undefined) {\n  useEffect(() => {\n    if (stateKey === undefined) return\n    const onMessage = (event: MessageEvent) => {\n      const frame = frameRef.current\n      if (frame === null || event.source !== frame.contentWindow) return\n      const values = readStateMessage(event.data, token)\n      if (values !== undefined) cardStates.write(stateKey, values)\n    }\n    addEventListener('message', onMessage)\n    return () => removeEventListener('message', onMessage)\n  }, [frameRef, token, stateKey])\n}\n\n/**\n * Relay this frame's `dshViz.prompt` requests into the sink. Only messages\n * from this very frame window count — the token is readable by the fragment\n * — and only while the reader is interacting with this frame (see\n * {@link readerIsInFrame}), at most once per interval.\n * @param frameRef - the card's iframe.\n * @param token - the frame's correlation token.\n * @param prompt - the injected sink, or undefined when prompts are off.\n */\nfunction usePromptRelay(frameRef: RefObject<HTMLIFrameElement | null>, token: string, prompt: PromptSink | undefined) {\n  const lastAt = useRef(-Infinity)\n  useEffect(() => {\n    if (prompt === undefined) return\n    const onMessage = (event: MessageEvent) => {\n      const frame = frameRef.current\n      if (frame === null || event.source !== frame.contentWindow) return\n      const text = readPromptMessage(event.data, token)\n      if (text === undefined || !readerIsInFrame(frame)) return\n      const now = performance.now()\n      if (now - lastAt.current < PROMPT_INTERVAL_MS) return\n      lastAt.current = now\n      prompt(text)\n    }\n    addEventListener('message', onMessage)\n    return () => removeEventListener('message', onMessage)\n  }, [frameRef, token, prompt])\n}\n\n/** What every surface of one card shares. */\ninterface FrameProps {\n  meta: VisualizeMeta\n  callId: string\n  prompt?: PromptSink | undefined\n  /** The card's saved-state key ({@link cardStateKey}); absent for a card still streaming. */\n  stateKey?: string | undefined\n}\n\n/** The sandboxed frame, sized to its content's reported height up to the mode's cap. */\nfunction SizedFrame({ meta, callId, prompt, stateKey }: FrameProps) {\n  const [height, setHeight] = useState(MIN_HEIGHT)\n  const frameRef = useRef<HTMLIFrameElement | null>(null)\n  usePromptRelay(frameRef, callId, prompt)\n  useStateRelay(frameRef, callId, stateKey)\n  useEffect(() => {\n    const onMessage = (event: MessageEvent) => {\n      const data: unknown = event.data\n      if (typeof data !== 'object' || data === null) return\n      const report = data as { type?: unknown; token?: unknown; height?: unknown }\n      if (report.type !== HEIGHT_MESSAGE_TYPE || report.token !== callId) return\n      if (typeof report.height !== 'number' || !Number.isFinite(report.height)) return\n      setHeight(Math.max(MIN_HEIGHT, Math.min(Math.ceil(report.height), HEIGHT_CAP[meta.mode])))\n    }\n    addEventListener('message', onMessage)\n    return () => removeEventListener('message', onMessage)\n  }, [callId, meta.mode])\n  const { doc, colorScheme } = useFrameDoc(\n    meta, callId, variantOf(meta), prompt !== undefined, stateKey === undefined ? undefined : { key: stateKey, saves: true },\n  )\n  return (\n    <iframe\n      ref={frameRef}\n      key={colorScheme}\n      sandbox={FRAME_SANDBOX}\n      referrerPolicy=\"no-referrer\"\n      title={meta.title}\n      srcDoc={doc}\n      style={{ ...frameStyle, height, colorScheme }}\n    />\n  )\n}\n\n/**\n * The settled, well-formed card: header line plus the sandboxed frame, or a\n * page card's launcher. Every surface that shows a card — the toolview, the\n * turn tail, replay — goes through here, so a page card is a launcher in all\n * of them.\n */\nexport function Frame({ meta: persisted, callId, prompt, stateKey }: FrameProps) {\n  // Every surface below builds from this meta, images already embedded.\n  const meta = useCardImages(persisted)\n  if (meta === undefined) return <div style={headerStyle}>{persisted.title} · {loadingImagesLabel()}</div>\n  if (meta.mode === 'page') return <PageLauncher meta={meta} callId={callId} prompt={prompt} stateKey={stateKey} />\n  const label = openLabel()\n  return (\n    <div style={cardStyle}>\n      <div style={headerStyle} title={meta.path === '' ? meta.title : meta.path}>\n        <span style={titleStyle}>{meta.title}</span>\n        {meta.path !== '' && <span style={pathStyle}>{meta.path}</span>}\n        <button\n          type=\"button\"\n          style={openStyle}\n          aria-label={label}\n          title={label}\n          onClick={() => openInWindow(meta, callId, stateKey)}\n        >\n          <OpenIcon />\n        </button>\n      </div>\n      <SizedFrame meta={meta} callId={callId} prompt={prompt} stateKey={stateKey} />\n    </div>\n  )\n}\n\n/**\n * Thumbnail geometry: the page lays out in a desktop viewport and the frame\n * is scaled down to the launcher's width, then clipped to a fixed height, so\n * the reader sees the top of the real page rather than a reflowed narrow one.\n */\nconst THUMB_VIEWPORT_WIDTH = 1280\nconst THUMB_VIEWPORT_HEIGHT = 800\nconst THUMB_HEIGHT = 220\n\nconst hostBorder = '1px solid var(--dsw-alias-border-l2, rgb(127 127 127 / 25%))'\n\nconst launcherStyle: CSSProperties = {\n  minWidth: 0,\n  maxWidth: '100%',\n  border: hostBorder,\n  borderRadius: 10,\n  overflow: 'hidden',\n}\n\nconst thumbStyle: CSSProperties = {\n  position: 'relative',\n  height: THUMB_HEIGHT,\n  overflow: 'hidden',\n  cursor: 'pointer',\n  background: 'var(--dsw-alias-bg-base, transparent)',\n  borderBottom: hostBorder,\n}\n\nconst launcherBarStyle: CSSProperties = {\n  display: 'flex',\n  flexWrap: 'wrap',\n  alignItems: 'center',\n  gap: '8px 12px',\n  padding: '10px 12px',\n}\n\nconst launcherTextStyle: CSSProperties = { flex: '1 1 220px', minWidth: 0 }\n\nconst oneLine: CSSProperties = { overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }\n\nconst launcherTitleStyle: CSSProperties = { ...oneLine, fontSize: 14, fontWeight: 500, lineHeight: 1.4 }\n\nconst launcherSummaryStyle: CSSProperties = { ...oneLine, fontSize: 12, lineHeight: 1.5, opacity: 0.65 }\n\nconst actionsStyle: CSSProperties = { display: 'flex', gap: 8, flexShrink: 0, marginLeft: 'auto' }\n\nconst buttonBase: CSSProperties = {\n  display: 'inline-flex',\n  alignItems: 'center',\n  gap: 6,\n  height: 30,\n  padding: '0 12px',\n  borderRadius: 8,\n  font: 'inherit',\n  fontSize: 13,\n  cursor: 'pointer',\n  whiteSpace: 'nowrap',\n}\n\nconst primaryButtonStyle: CSSProperties = {\n  ...buttonBase,\n  border: '1px solid transparent',\n  background: 'var(--dsw-alias-brand-primary-new-colorprimary-new-color, rgb(65 118 230))',\n  color: 'var(--dsw-alias-label-primary-inverted, rgb(255 255 255))',\n  fontWeight: 500,\n}\n\nconst ghostButtonStyle: CSSProperties = { ...buttonBase, border: hostBorder, background: 'transparent', color: 'inherit' }\n\n/** Launcher strings, in the host's language. */\nfunction launcherLabels() {\n  return hostIsZh()\n    ? { open: '打开页面', show: '在对话中展开', hide: '收起', kind: '独立页面' }\n    : { open: 'Open page', show: 'Show here', hide: 'Collapse', kind: 'Standalone page' }\n}\n\n/**\n * The live, inert thumbnail of a page: the same sandboxed page document, laid\n * out at desktop width and scaled into the launcher. Pointer events and focus\n * stay out of the frame, so it never takes a click, a scroll, or a tab stop;\n * a click on the thumbnail opens the page like the button does.\n */\nfunction PageThumbnail({ meta, callId, stateKey, onOpen }: FrameProps & { onOpen: (() => void) | undefined }) {\n  const wrapRef = useRef<HTMLDivElement | null>(null)\n  const [width, setWidth] = useState(0)\n  useEffect(() => {\n    const wrap = wrapRef.current\n    if (wrap === null) return\n    const measure = () => setWidth(wrap.clientWidth)\n    measure()\n    if (typeof ResizeObserver !== 'function') return\n    const observer = new ResizeObserver(measure)\n    observer.observe(wrap)\n    return () => observer.disconnect()\n  }, [])\n  // A distinct token: its height reports must never size another frame.\n  // It shows the saved state but, inert, never changes it.\n  const { doc, colorScheme } = useFrameDoc(\n    meta, `thumb:${callId}`, 'page', false, stateKey === undefined ? undefined : { key: stateKey, saves: false },\n  )\n  const scale = width > 0 ? width / THUMB_VIEWPORT_WIDTH : 0.5\n  return (\n    <div ref={wrapRef} style={thumbStyle} aria-hidden=\"true\" onClick={onOpen}>\n      <iframe\n        key={colorScheme}\n        sandbox={FRAME_SANDBOX}\n        referrerPolicy=\"no-referrer\"\n        title={meta.title}\n        srcDoc={doc}\n        tabIndex={-1}\n        style={{\n          display: 'block',\n          position: 'absolute',\n          top: 0,\n          left: 0,\n          width: THUMB_VIEWPORT_WIDTH,\n          height: THUMB_VIEWPORT_HEIGHT,\n          border: 0,\n          transform: `scale(${scale})`,\n          transformOrigin: '0 0',\n          pointerEvents: 'none',\n          colorScheme,\n        }}\n      />\n    </div>\n  )\n}\n\n/**\n * A page card in the conversation: not the page itself, which is built for a\n * whole tab, but a launcher for it. Opening is always the reader's click — a\n * tab opened without a user gesture is a blocked popup. Where no tab can be\n * opened at all, the page renders in place as a regular card.\n */\nfunction PageLauncher({ meta, callId, prompt, stateKey }: FrameProps) {\n  const opens = canOpenWindow()\n  const [expanded, setExpanded] = useState(!opens)\n  const labels = launcherLabels()\n  const open = opens ? () => openInWindow(meta, callId, stateKey) : undefined\n  return (\n    <div style={launcherStyle} data-visualize-launcher=\"\">\n      {expanded\n        ? <SizedFrame meta={meta} callId={callId} prompt={prompt} stateKey={stateKey} />\n        : <PageThumbnail meta={meta} callId={callId} stateKey={stateKey} onOpen={open} />}\n      <div style={launcherBarStyle}>\n        <div style={launcherTextStyle} title={meta.path === '' ? meta.title : meta.path}>\n          <div style={launcherTitleStyle}>{meta.title}</div>\n          <div style={launcherSummaryStyle}>{meta.summary ?? labels.kind}</div>\n        </div>\n        {open !== undefined && (\n          <div style={actionsStyle}>\n            <button type=\"button\" style={ghostButtonStyle} aria-expanded={expanded} onClick={() => setExpanded(on => !on)}>\n              {expanded ? labels.hide : labels.show}\n            </button>\n            <button type=\"button\" style={primaryButtonStyle} onClick={open}>\n              <OpenIcon />\n              {labels.open}\n            </button>\n          </div>\n        )}\n      </div>\n    </div>\n  )\n}\n\n/**\n * Keyed toolview for the `visualize` tool. Running calls and malformed or\n * failed results stay quiet single lines; a well-formed persisted meta — or\n * the fragment in the call's own arguments for nested dispatches — mounts\n * the frame. Only a settled card relays prompts.\n */\nexport function VisualizeCard({ callId, block, visualizePrompt, visualizeSession }: ToolCallViewProps & VisualizePromptInjected) {\n  // dsh 0.1.7 adds a preparing phase whose block carries no arguments yet.\n  const argsRaw = 'kind' in block ? block.call?.argsRaw : 'argsRaw' in block ? block.argsRaw : undefined\n  if (!('kind' in block)) {\n    const live = visualizeMetaFromArgs(argsRaw)\n    if (live !== undefined) return <Frame meta={{ ...live, style: liveStyle() }} callId={callId} />\n    return <div style={headerStyle}>Visualize · rendering…</div>\n  }\n  if (block.isError) {\n    return <div style={headerStyle}>Visualize · {firstResultLine(block.content)}</div>\n  }\n  const persisted = visualizeMetaFrom(block.meta)\n  if (persisted !== undefined) noteSettledStyle(persisted.style, argsRaw)\n  const fromArgs = persisted === undefined ? visualizeMetaFromArgs(argsRaw) : undefined\n  const meta = persisted ?? (fromArgs === undefined ? undefined : { ...fromArgs, style: liveStyle() })\n  if (meta === undefined) {\n    // A settled call without either the descriptor or a parseable fragment:\n    // show the durable result text instead of guessing at markup.\n    return <div style={headerStyle}>{firstResultLine(block.content)}</div>\n  }\n  return <Frame meta={meta} callId={callId} prompt={visualizePrompt} stateKey={cardStateKey(visualizeSession, meta.path, callId)} />\n}\n\n/** Props a slot registration injects so cards can reach their session. */\nexport interface VisualizePromptInjected {\n  /** Composer sink for this session; absent on hosts without a session input. */\n  visualizePrompt?: PromptSink | undefined\n  /** The session the card renders in, part of its saved-state key; absent where the host passes none. */\n  visualizeSession?: string | undefined\n}\n\n/**\n * What a slot registration injects for one session.\n * @param prompt - the session's composer sink.\n * @param sessionId - the session id the registration's inject received.\n * @returns the injected props.\n */\nexport function sessionInjection(prompt: PromptSink | undefined, sessionId: unknown): VisualizePromptInjected {\n  return {\n    visualizePrompt: prompt,\n    visualizeSession: typeof sessionId === 'string' && sessionId !== '' ? sessionId : undefined,\n  }\n}\n"
    },
    {
      "path": "src/client/card-state.ts",
      "content": "/**\n * Where a card's interaction state lives between loads: what the reader set\n * through `data-viz-keep` controls and `dshViz.state` (viz-helper.ts), so a\n * page refresh, a reopened session, a theme switch or a patch brings the card\n * back as the reader left it.\n *\n * Storage is the dsh web page's `localStorage`, one entry per card under\n * {@link STORAGE_PREFIX}. The host offers no client-side per-session store\n * to plugins (its own persisted UI stores are `localStorage` too), so state\n * is per browser profile and per dsh origin, and does not follow the session\n * to another device. Every access is wrapped: a browser that refuses storage\n * (private mode, blocked site data, quota) still keeps state in memory for\n * the life of the page.\n *\n * Identity: a card is its session plus its `path`. A create takes a\n * content-addressed path (`<slug>-<hash>`), so new markup starts clean, while\n * an `update` patches the same path and keeps what the reader set: a patch is\n * almost always a correction the reader asked for while looking at their own\n * settings. A kept control that no longer accepts its value (a removed\n * option, a type that changed) is left at its markup default by the frame.\n * Cards without a path (arguments-only replays) fall back to their call id.\n *\n * Trust: the frame runs model-written script, so the card takes a state\n * message only from its own frame window with its token, decides the key\n * itself (the message never names one), caps each card at\n * {@link CARD_STATE_MAX_CHARS} and all cards together at\n * {@link STATE_TOTAL_MAX_CHARS}, evicting the cards changed longest ago.\n * Writes are debounced and flushed when the page hides.\n *\n * @module @nagi-ovo/dsh-visualize/client/card-state\n */\n\nimport { CARD_STATE_MAX_CHARS, STATE_MESSAGE_TYPE, type CardState } from '../viz-helper.ts'\n\nexport { CARD_STATE_MAX_CHARS }\n\n/** Prefix of every `localStorage` key this module owns. */\nexport const STORAGE_PREFIX = 'dsh-visualize:state:'\n\n/**\n * Most characters (keys plus JSON) all saved cards may take in `localStorage`.\n * The origin's quota (about 5 MB) is shared with the host's own stores.\n */\nexport const STATE_TOTAL_MAX_CHARS = 256 * 1024\n\n/** Quiet period after the last change before it is written. */\nexport const STATE_WRITE_DELAY_MS = 400\n\n/** The slice of `Storage` the store uses. */\nexport interface StateStorage {\n  readonly length: number\n  key(index: number): string | null\n  getItem(key: string): string | null\n  setItem(key: string, value: string): void\n  removeItem(key: string): void\n}\n\n/** One card's state as stored: when it last changed, and its values. */\ninterface StoredEntry {\n  t: number\n  s: CardState\n}\n\n/**\n * The key a card's state is kept under.\n * @param session - the card's session id, when the host provides one.\n * @param path - the card's path from its meta; empty for arguments-only cards.\n * @param callId - the producing call id, the identity of a card without a path.\n * @returns the store key.\n */\nexport function cardStateKey(session: string | undefined, path: string, callId: string): string {\n  return `${session ?? ''}|${path === '' ? `call:${callId}` : path}`\n}\n\n/**\n * Whether a value is a plain JSON-style object (not an array, class instance or null).\n * @param value - candidate.\n * @returns true for a plain object.\n */\nfunction isPlainObject(value: unknown): value is Record<string, unknown> {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false\n  const proto = Object.getPrototypeOf(value) as unknown\n  return proto === Object.prototype || proto === null\n}\n\n/**\n * Normalise a state object through JSON, within the per-card cap.\n * @param value - candidate state.\n * @param maxChars - cap on its JSON length.\n * @returns the JSON-clean state and its JSON, or undefined when it is not one or too big.\n */\nfunction cleanState(value: unknown, maxChars: number): { values: CardState; json: string } | undefined {\n  if (!isPlainObject(value)) return undefined\n  let json: string\n  try {\n    json = JSON.stringify(value)\n  } catch {\n    // Cycles and BigInts survive structured clone but not JSON.\n    return undefined\n  }\n  if (json.length > maxChars) return undefined\n  return { values: JSON.parse(json) as CardState, json }\n}\n\n/**\n * Read one frame message as a state snapshot.\n * @param data - the message payload.\n * @param token - this frame's correlation token.\n * @param maxChars - per-card cap on the snapshot's JSON.\n * @returns the snapshot, or undefined when the message is not a valid one.\n */\nexport function readStateMessage(data: unknown, token: string, maxChars = CARD_STATE_MAX_CHARS): CardState | undefined {\n  if (typeof data !== 'object' || data === null) return undefined\n  const message = data as { type?: unknown; token?: unknown; state?: unknown }\n  if (message.type !== STATE_MESSAGE_TYPE || message.token !== token) return undefined\n  return cleanState(message.state, maxChars)?.values\n}\n\n/** A store of card states. */\nexport interface CardStateStore {\n  /**\n   * The state a card should start from: the latest change this page saw, or\n   * what storage holds.\n   * @param key - from {@link cardStateKey}.\n   * @returns a copy of the values, or undefined when nothing is saved.\n   */\n  read(key: string): CardState | undefined\n  /**\n   * Record a card's new state; storage is written after the quiet period.\n   * @param key - from {@link cardStateKey}.\n   * @param values - the whole state, already JSON-clean.\n   */\n  write(key: string, values: CardState): void\n  /** Write every pending change now. */\n  flush(): void\n}\n\n/** Limits and clock of one store. */\nexport interface CardStateOptions {\n  cardMaxChars?: number\n  totalMaxChars?: number\n  delayMs?: number\n  now?: () => number\n}\n\n/**\n * Create a store over a storage accessor.\n * @param storage - returns the storage, or undefined (or throws) where there is none.\n * @param options - limits and clock; tests shrink them.\n * @returns the store.\n */\nexport function createCardStateStore(storage: () => StateStorage | undefined, options: CardStateOptions = {}): CardStateStore {\n  const cardMax = options.cardMaxChars ?? CARD_STATE_MAX_CHARS\n  const totalMax = options.totalMaxChars ?? STATE_TOTAL_MAX_CHARS\n  const delay = options.delayMs ?? STATE_WRITE_DELAY_MS\n  const now = options.now ?? Date.now\n  // Latest known state per card for this page, so a frame rebuilt before the\n  // write lands (or when storage refuses it) still starts from it.\n  const memory = new Map<string, string>()\n  const pending = new Set<string>()\n  let timer: ReturnType<typeof setTimeout> | undefined\n\n  function open(): StateStorage | undefined {\n    try {\n      return storage()\n    } catch {\n      return undefined\n    }\n  }\n\n  function parseEntry(raw: string | null): StoredEntry | undefined {\n    if (raw === null) return undefined\n    try {\n      const entry = JSON.parse(raw) as Partial<StoredEntry> | null\n      if (entry === null || typeof entry !== 'object') return undefined\n      const state = cleanState(entry.s, cardMax)\n      if (state === undefined) return undefined\n      return { t: typeof entry.t === 'number' && Number.isFinite(entry.t) ? entry.t : 0, s: state.values }\n    } catch {\n      return undefined\n    }\n  }\n\n  /** Our other entries in storage, oldest change first. */\n  function others(store: StateStorage, except: string): { key: string; size: number; t: number }[] {\n    const found: { key: string; size: number; t: number }[] = []\n    for (let i = 0; i < store.length; i++) {\n      const key = store.key(i)\n      if (key === null || !key.startsWith(STORAGE_PREFIX) || key === except) continue\n      const raw = store.getItem(key) ?? ''\n      found.push({ key, size: key.length + raw.length, t: parseEntry(raw)?.t ?? 0 })\n    }\n    return found.sort((a, b) => a.t - b.t)\n  }\n\n  function persist(store: StateStorage, key: string, json: string): void {\n    const full = STORAGE_PREFIX + key\n    if (json === '{}') {\n      store.removeItem(full)\n      return\n    }\n    const value = `{\"t\":${now()},\"s\":${json}}`\n    const victims = others(store, full)\n    let used = victims.reduce((sum, entry) => sum + entry.size, 0)\n    while (used + full.length + value.length > totalMax && victims.length > 0) {\n      const oldest = victims.shift()!\n      store.removeItem(oldest.key)\n      used -= oldest.size\n    }\n    // The host's stores share the quota: when it is full, give up our own\n    // oldest cards before this one.\n    for (;;) {\n      try {\n        store.setItem(full, value)\n        return\n      } catch (error) {\n        const oldest = victims.shift()\n        if (oldest === undefined) throw error\n        store.removeItem(oldest.key)\n      }\n    }\n  }\n\n  function flush(): void {\n    if (timer !== undefined) clearTimeout(timer)\n    timer = undefined\n    if (pending.size === 0) return\n    const keys = [...pending]\n    pending.clear()\n    const store = open()\n    if (store === undefined) return\n    for (const key of keys) {\n      try {\n        persist(store, key, memory.get(key) ?? '{}')\n      } catch {\n        // Storage refused it; the page keeps it in memory.\n      }\n    }\n  }\n\n  return {\n    read(key) {\n      let json = memory.get(key)\n      if (json === undefined) {\n        try {\n          const entry = parseEntry(open()?.getItem(STORAGE_PREFIX + key) ?? null)\n          if (entry !== undefined) json = JSON.stringify(entry.s)\n        } catch {\n          // Unreadable storage reads as nothing saved.\n        }\n        if (json !== undefined) memory.set(key, json)\n      }\n      return json === undefined || json === '{}' ? undefined : JSON.parse(json) as CardState\n    },\n    write(key, values) {\n      const state = cleanState(values, cardMax)\n      if (state === undefined || memory.get(key) === state.json) return\n      memory.set(key, state.json)\n      pending.add(key)\n      if (timer !== undefined) clearTimeout(timer)\n      timer = setTimeout(flush, delay)\n    },\n    flush,\n  }\n}\n\n/**\n * The page's `localStorage`, or undefined where reading it throws (blocked\n * site data) or it does not exist.\n * @returns the storage.\n */\nfunction pageStorage(): StateStorage | undefined {\n  return typeof window === 'undefined' ? undefined : window.localStorage\n}\n\n/** The store every card on the page shares. */\nexport let cardStates: CardStateStore = createCardStateStore(pageStorage)\n\n/**\n * Replace the shared store with a fresh one over another storage (tests only).\n * @param storage - the storage accessor.\n * @param options - limits and clock.\n */\nexport function resetCardStates(storage: () => StateStorage | undefined = pageStorage, options?: CardStateOptions): void {\n  cardStates = createCardStateStore(storage, options)\n}\n\nif (typeof window !== 'undefined') {\n  // Changes inside the quiet period would otherwise be lost to a reload.\n  addEventListener('pagehide', () => cardStates.flush())\n  document.addEventListener('visibilitychange', () => {\n    if (document.visibilityState === 'hidden') cardStates.flush()\n  })\n}\n"
    },
    {
      "path": "src/client/prompt-bridge.ts",
      "content": "/**\n * The card→composer bridge behind `dshViz.prompt`: a frame asks for some text\n * to be put into the chat composer, and the card puts it there as a draft the\n * reader reviews and sends. Nothing is ever sent on the frame's behalf — the\n * frame runs model-written script, so the reader stays the one who speaks.\n *\n * Every gate lives on the parent side, since the frame's own code is\n * untrusted: the message must come from this card's own frame window (the\n * token alone is readable by the fragment), while the reader is interacting\n * with that frame (so a card cannot fill the draft on load), within the\n * length and rate limits, and into an idle composer that is empty or still\n * holds exactly the text a card put there last — `setDraft` replaces the\n * whole draft, chips included, so a draft the reader wrote or edited is never\n * overwritten, while a reader who changes their pick just replaces it.\n *\n * Host surface (dsh 0.1.7+): `sessions.scope(id).get('conversation').input\n * .for(scope)` yields the session's input facade (`setDraft`, `focus`,\n * `notify`, `state`). Older hosts lack it and the bridge stays off.\n *\n * @module @nagi-ovo/dsh-visualize/client/prompt-bridge\n */\n\nimport { PROMPT_MESSAGE_TYPE } from '../shell.ts'\n\n/** Longest prompt text accepted, in UTF-16 code units. */\nexport const PROMPT_MAX_CHARS = 2000\n\n/**\n * Minimum gap between two accepted prompts from one frame: enough to drop a\n * double click, short enough that a reader changing their pick is not lost.\n */\nexport const PROMPT_INTERVAL_MS = 300\n\n/** What became of one prompt request. */\nexport type PromptOutcome =\n  /** The text is in the composer, focused, waiting for the reader. */\n  | 'drafted'\n  /** The reader already has a draft; it stays and a notice says why. */\n  | 'kept-draft'\n  /** The composer is mid-submission; nothing changed. */\n  | 'busy'\n  /** The host or session offers no input facade. */\n  | 'unavailable'\n\n/** Card-side sink a registration injects: put text into this session's composer. */\nexport type PromptSink = (text: string) => PromptOutcome\n\n/** The slice of the host's per-session input facade the bridge uses. */\nexport interface ComposerInput {\n  setDraft(text: string): void\n  focus?(): void\n  notify?(level: 'info' | 'error', text: string): void\n  readonly state?: { getSnapshot(): { readonly draft?: string; readonly phase?: string } }\n}\n\n/**\n * Read one frame message as a prompt request.\n * @param data - the message payload.\n * @param token - this frame's correlation token.\n * @returns the cleaned prompt text, or undefined when the message is not a valid prompt.\n */\nexport function readPromptMessage(data: unknown, token: string): string | undefined {\n  if (typeof data !== 'object' || data === null) return undefined\n  const message = data as { type?: unknown; token?: unknown; text?: unknown }\n  if (message.type !== PROMPT_MESSAGE_TYPE || message.token !== token) return undefined\n  if (typeof message.text !== 'string') return undefined\n  // Control characters other than tab and newline have no place in a draft.\n  // eslint-disable-next-line no-control-regex\n  const text = message.text.replace(/[\\u0000-\\u0008\\u000B-\\u001F\\u007F]/gu, '').trim()\n  if (text === '' || text.length > PROMPT_MAX_CHARS) return undefined\n  return text\n}\n\n/**\n * Whether the reader is interacting with this frame right now. Activation\n * alone is not enough: it lingers for seconds after any click on the chat\n * page, so a card that loads right after the reader opens a session would\n * pass. Focus pins it to this frame — a click inside the frame makes it the\n * page's active element, and a cross-origin frame cannot take focus without\n * the reader's own gesture. Browsers without `userActivation` rely on focus.\n * @param frame - the card's iframe.\n * @returns true when the frame holds focus during a user activation.\n */\nexport function readerIsInFrame(frame: HTMLIFrameElement): boolean {\n  if (frame.ownerDocument.activeElement !== frame) return false\n  const activation = (navigator as { userActivation?: { isActive?: boolean } }).userActivation\n  return typeof activation?.isActive !== 'boolean' || activation.isActive\n}\n\n/**\n * Put prompt text into the composer when it is idle and holds nothing of the\n * reader's own: empty, or exactly what a card drafted there last.\n * @param input - the session's input facade.\n * @param text - cleaned prompt text.\n * @param carded - the text a card last drafted in this session, if any.\n * @returns the outcome.\n */\nexport function draftPrompt(input: ComposerInput, text: string, carded?: string): PromptOutcome {\n  const state = input.state?.getSnapshot()\n  if (state?.phase !== undefined && state.phase !== 'plain') return 'busy'\n  const draft = state?.draft?.trim() ?? ''\n  if (draft !== '' && draft !== carded) {\n    input.notify?.('info', keptDraftNotice())\n    return 'kept-draft'\n  }\n  input.setDraft(text)\n  input.focus?.()\n  return 'drafted'\n}\n\n/** Minimal host shape the sink resolves through, feature-detected at call time. */\ninterface SessionsHost {\n  get(name: string): unknown\n}\n\n/**\n * Resolve a session's input facade, or undefined on hosts without one.\n * @param host - client context.\n * @param sessionId - the session the card belongs to.\n * @returns the facade.\n */\nexport function composerFor(host: SessionsHost, sessionId: unknown): ComposerInput | undefined {\n  if (typeof sessionId !== 'string' || sessionId === '') return undefined\n  try {\n    const sessions = host.get('sessions') as { scope?(id: string): SessionsHost | undefined } | undefined\n    const scope = typeof sessions?.scope === 'function' ? sessions.scope(sessionId) : undefined\n    const conversation = scope?.get('conversation') as { input?: { for?(scope: unknown): unknown } } | undefined\n    if (scope === undefined || typeof conversation?.input?.for !== 'function') return undefined\n    const input = conversation.input.for(scope) as Partial<ComposerInput> | undefined\n    return typeof input?.setDraft === 'function' ? input as ComposerInput : undefined\n  } catch {\n    // `input.for` throws for a session that is no longer retained.\n    return undefined\n  }\n}\n\n/**\n * The sink a slot registration injects for one session, or undefined where\n * the host has no session input facade (dsh before 0.1.7) — the card then\n * builds its frame with `canPrompt` false. The facade itself resolves on\n * every prompt, so a session that went away since mount just declines.\n * @param host - client context.\n * @param sessionId - the session the card renders in.\n * @returns the sink, or undefined.\n */\nexport function promptSinkFor(host: SessionsHost, sessionId: unknown): PromptSink | undefined {\n  if (typeof sessionId !== 'string' || sessionId === '') return undefined\n  try {\n    const sessions = host.get('sessions') as { scope?(id: string): SessionsHost | undefined } | undefined\n    const scope = typeof sessions?.scope === 'function' ? sessions.scope(sessionId) : undefined\n    const conversation = scope?.get('conversation') as { input?: { for?: unknown } } | undefined\n    if (typeof conversation?.input?.for !== 'function') return undefined\n  } catch {\n    return undefined\n  }\n  return (text) => {\n    const input = composerFor(host, sessionId)\n    if (input === undefined) return 'unavailable'\n    const outcome = draftPrompt(input, text, cardDrafts.get(sessionId))\n    if (outcome === 'drafted') cardDrafts.set(sessionId, text)\n    return outcome\n  }\n}\n\n/**\n * The text a card last put into each session's composer. A draft still equal\n * to it is the card's, not the reader's, so a new pick may replace it.\n */\nconst cardDrafts = new Map<string, string>()\n\n/** Notice shown when a card's prompt meets a draft the reader is writing. */\nfunction keptDraftNotice(): string {\n  return document.documentElement.lang.toLowerCase().startsWith('zh')\n    ? '输入框里已有草稿，卡片的内容没有写入'\n    : 'The composer already has a draft, so the card’s text was not inserted'\n}\n"
    },
    {
      "path": "src/fragment.ts",
      "content": "/**\n * Pure fragment contract shared by the tool (validation at execute time), the\n * browser card (meta narrowing at render time), and the specs. No I/O and no\n * DOM so both halves and vitest can load it unchanged.\n *\n * A *fragment* is the model-authored inline-HTML body of one visualization:\n * literal markup without a document skeleton. The card owns the skeleton — it\n * wraps the fragment in a sandboxed iframe document with its own CSP — so a\n * fragment that ships its own `<!doctype>`/`<html>`/`<head>`/`<body>` would\n * nest documents and is rejected loudly instead of rendered broken (see\n * `lint.ts` for that rule and the rest of the contract's rule table).\n *\n * @module @nagi-ovo/dsh-visualize/fragment\n */\n\nimport { DEFAULT_STYLE, styleIdFrom, type StyleId } from './style.ts'\n\n/**\n * Wire name of the tool, the keyed toolview, and the streaming-preview match.\n * Lives in this pure module so the browser half can import it without pulling\n * the node-side tool implementation into the client bundle.\n */\nexport const VISUALIZE_TOOL_NAME = 'visualize'\n\n/**\n * Surface of one visualization: `inline` and `wide` render the fragment in\n * the conversation at the chat column's or the expanded width; `page` renders\n * a launcher card there and the fragment itself as a full page in its own tab.\n */\nexport type VisualizeMode = 'inline' | 'wide' | 'page'\n\n/** Every {@link VisualizeMode}, in the order the tool schema lists them. */\nexport const VISUALIZE_MODES: readonly VisualizeMode[] = ['inline', 'wide', 'page']\n\n/**\n * Narrow one wire value to a {@link VisualizeMode}.\n * @param value - the raw value.\n * @returns whether it names a known mode.\n */\nexport function isVisualizeMode(value: unknown): value is VisualizeMode {\n  return value === 'inline' || value === 'wide' || value === 'page'\n}\n\n/**\n * What one `visualize` call does: render a card from whole markup, or patch\n * the markup of a card an earlier call already rendered.\n */\nexport type VisualizeAction = 'create' | 'update'\n\n/** The `tool/result` meta descriptor persisted for replay-stable rendering. */\nexport interface VisualizeMeta {\n  /** Discriminant for consumers sharing the meta channel. */\n  kind: 'visualize'\n  /** The validated fragment body, inlined so replay never re-reads the file. */\n  fragment: string\n  /** Concise human title shown in the card header. */\n  title: string\n  /** Surface; `wide` asks for the expanded inline surface, `page` for a launcher and its own tab. */\n  mode: VisualizeMode\n  /** Session-relative or absolute source path, kept for provenance display. */\n  path: string\n  /** One-line description a page launcher shows under its title; absent when none was given. */\n  summary?: string\n  /**\n   * Card style the card was created under, so replay and the windowed view\n   * keep its look after the setting changes. Absent on cards from before\n   * styles existed, which read as the default.\n   */\n  style: StyleId\n  /**\n   * Images the tool resolved from the fragment's `data-viz-src` attributes,\n   * as references only: the bytes stay in the plugin's card store and reach\n   * the card through {@link IMAGE_ROUTE_PATH}. Absent when there are none.\n   */\n  images?: CardImage[]\n}\n\n/** Image formats a card embeds; the tool verifies each by its magic bytes. */\nexport type CardImageType = 'image/png' | 'image/jpeg' | 'image/gif' | 'image/webp' | 'image/svg+xml'\n\n/** Every {@link CardImageType}. */\nexport const CARD_IMAGE_TYPES: readonly CardImageType[] = ['image/png', 'image/jpeg', 'image/gif', 'image/webp', 'image/svg+xml']\n\n/** One resolved `data-viz-src`, as persisted meta carries it. */\nexport interface CardImage {\n  /** The attribute value exactly as the fragment spells it, entities undecoded. */\n  src: string\n  /** Store id the image route serves: `<session segment>/<sha256>.<ext>`. */\n  id: string\n  type: CardImageType\n  bytes: number\n}\n\n/**\n * Exact route on the host's authenticated `/api` channel (dsh 0.1.7+) that\n * serves a stored card image by its {@link CardImage.id}.\n */\nexport const IMAGE_ROUTE_PATH = '/api/dsh-visualize/image'\n\n/**\n * Characters of real card content quoted back when a patch fails to apply, so\n * the model can correct `old_str` from the true bytes without re-reading the\n * whole card.\n */\nconst PATCH_CONTEXT_CHARS = 160\n\n/**\n * Shortest matching prefix of a failed `old_str` still worth reporting as a\n * location hint; below this any HTML shares enough characters to point\n * somewhere misleading.\n */\nconst MIN_ANCHOR_CHARS = 12\n\n/**\n * Replace one exact, unique occurrence of `oldStr` in a rendered card's\n * fragment. Iterating by patch instead of re-emitting the whole fragment is\n * what keeps a small correction small: the model re-states only the changed\n * region, and the card's markup never enters its output twice.\n *\n * A patch that does not resolve to exactly one site is refused rather than\n * guessed at, because both wrong outcomes are silent — a near-miss would edit\n * markup the model never saw, and an ambiguous match would edit an arbitrary\n * one of several sites. The thrown message carries the surrounding real\n * content so the caller can correct `old_str` within the same turn.\n *\n * @param base - the current fragment of the card being patched.\n * @param oldStr - exact text to replace, whitespace included.\n * @param newStr - replacement text; empty deletes the matched region.\n * @returns the patched fragment.\n * @throws Error naming why the patch did not apply; the tool surfaces it as `isError`.\n */\nexport function applyFragmentPatch(base: string, oldStr: string, newStr: string): string {\n  if (oldStr.length === 0) {\n    throw new Error('invalid visualization patch: old_str is empty — pass the exact card text to replace')\n  }\n  const first = base.indexOf(oldStr)\n  if (first === -1) {\n    throw new Error(`invalid visualization patch: old_str does not appear in the card. ${nearestAnchor(base, oldStr)}`)\n  }\n  if (base.indexOf(oldStr, first + oldStr.length) !== -1) {\n    throw new Error(\n      `invalid visualization patch: old_str appears ${countOccurrences(base, oldStr)} times in the card — `\n      + 'extend it with neighbouring lines until exactly one site matches',\n    )\n  }\n  return base.slice(0, first) + newStr + base.slice(first + oldStr.length)\n}\n\n/**\n * Describe where a failed `old_str` stopped matching: the longest prefix of it\n * that does occur, and the card's real text at that site. Prefix occurrence is\n * monotone in length, so the longest one is a binary search.\n * @param base - the current fragment of the card being patched.\n * @param oldStr - the `old_str` that failed to match.\n * @returns a sentence naming the divergence point, or advising a full re-render.\n */\nfunction nearestAnchor(base: string, oldStr: string): string {\n  let matched = 0\n  let beyond = oldStr.length\n  while (matched < beyond) {\n    const mid = Math.ceil((matched + beyond) / 2)\n    if (base.includes(oldStr.slice(0, mid))) matched = mid\n    else beyond = mid - 1\n  }\n  if (matched < MIN_ANCHOR_CHARS) {\n    return 'None of it matched, so the card is not in the state you assumed — re-render the whole card instead.'\n  }\n  const at = base.indexOf(oldStr.slice(0, matched))\n  return `Its first ${matched} characters do match, at offset ${at}, where the card actually reads `\n    + `${JSON.stringify(base.slice(at, at + PATCH_CONTEXT_CHARS))} — correct old_str against that and retry.`\n}\n\n/**\n * Count non-overlapping occurrences of a needle, matching the replacement\n * semantics {@link applyFragmentPatch} would apply.\n * @param base - the text to scan.\n * @param needle - the non-empty needle to count.\n * @returns the number of non-overlapping occurrences.\n */\nfunction countOccurrences(base: string, needle: string): number {\n  let count = 0\n  for (let at = base.indexOf(needle); at