      "path": "src/shell.ts",
      "content": "/**\n * Pure assembly of the sandboxed frame document a visualization renders in.\n * DOM-free so the node-side specs exercise it directly; the browser card is\n * its only production caller.\n *\n * Security model (aligned with Codex's /visualize render pipeline): the card\n * mounts `<iframe sandbox=\"allow-scripts\">` — an opaque origin with no access\n * to the host page — and this document's own CSP meta tag confines what runs\n * inside: inline script/style plus a fixed CDN allowlist, no fetch/XHR/\n * WebSocket (`connect-src` covers only blob/data), no nested frames, no form\n * posts. The allowlist is a protocol constant shared with the bundled skill\n * text, not configuration.\n *\n * @module @nagi-ovo/dsh-visualize/shell\n */\n\nimport { FRAME_CSS, PAGE_CSS } from './frame-css.ts'\nimport { DEFAULT_STYLE, STYLES, type StyleId } from './style.ts'\nimport { vizHelperScript, type CardState } from './viz-helper.ts'\n\n/** CDN origins a fragment may load static resources from. */\nexport const RESOURCE_ORIGINS = [\n  'https://cdnjs.cloudflare.com',\n  'https://cdn.jsdelivr.net',\n  'https://esm.sh',\n  'https://fonts.bunny.net',\n  'https://fonts.googleapis.com',\n  'https://fonts.gstatic.com',\n  'https://unpkg.com',\n] as const\n\nconst RESOURCE_SOURCES = ['blob:', 'data:', ...RESOURCE_ORIGINS].join(' ')\n\n/** The frame document's Content-Security-Policy. */\nexport const FRAME_CSP = [\n  \"default-src 'none'\",\n  `script-src 'unsafe-inline' 'unsafe-eval' 'wasm-unsafe-eval' ${RESOURCE_SOURCES}`,\n  `style-src 'unsafe-inline' ${RESOURCE_SOURCES}`,\n  `img-src ${RESOURCE_SOURCES}`,\n  `font-src ${RESOURCE_SOURCES}`,\n  `media-src ${RESOURCE_SOURCES}`,\n  \"worker-src blob:\",\n  'connect-src blob: data:',\n  \"frame-src 'none'\",\n  \"object-src 'none'\",\n  \"base-uri 'none'\",\n  \"form-action 'none'\",\n].join('; ')\n\n/** Wire type of the frame→card height report message. */\nexport const HEIGHT_MESSAGE_TYPE = 'dsh-visualize:height'\n\n/** Wire type of the card→frame streaming fragment update message. */\nexport const STREAM_MESSAGE_TYPE = 'dsh-visualize:stream'\n\nexport { PROMPT_MESSAGE_TYPE, STATE_MESSAGE_TYPE } from './viz-helper.ts'\n\n/** Inputs to one frame document assembly. */\nexport interface FrameDocOptions {\n  /** The validated fragment body. */\n  fragment: string\n  /** Document title (escaped here). */\n  title: string\n  /**\n   * Host palette bridged into the frame as `--dsh-viz-*` custom properties on\n   * `:root`. Values pass through {@link sanitizeCssValue}; entries that\n   * sanitize to empty are dropped so the stylesheet fallbacks apply.\n   */\n  themeVars: Record<string, string>\n  /** Host `color-scheme` so `light-dark()` in the frame follows the host theme. */\n  colorScheme: 'light' | 'dark'\n  /**\n   * Correlation token echoed in every height report, letting a card with\n   * several sibling frames attribute messages; the tool callId in production.\n   */\n  reportToken: string\n  /**\n   * Which surface the document fills: `card` (default) sits in the chat\n   * column with a small inset and a transparent body; `page` fills a browser\n   * tab with an opaque surface and the page layout classes ({@link PAGE_CSS}).\n   * The CSP and the height reporter are the same for both.\n   */\n  variant?: FrameVariant\n  /**\n   * Card style (style.ts) whose tokens, webfont and scoped CSS the frame\n   * takes; its token values win over the bridged host palette. Defaults to\n   * `whale`, which adds nothing to the host bridge. Applies to both variants.\n   */\n  style?: StyleId\n  /**\n   * Whether the embedding card relays `dshViz.prompt` into the composer: only\n   * a settled in-chat card on a host with a session input does. Tabs opened\n   * with \"open in new window\", thumbnails and the streaming preview leave it\n   * off, and the frame then reports `dshViz.canPrompt === false`.\n   */\n  promptable?: boolean\n  /**\n   * Values the card saved through `dshViz.state` and `data-viz-keep` on an\n   * earlier load, baked into the document so fragment scripts read them\n   * before anything async. Every surface that knows the card passes them; a\n   * thumbnail or a new tab thus opens where the reader left the card.\n   */\n  savedState?: CardState | undefined\n  /**\n   * Whether the embedding card stores the frame's state changes: only a\n   * settled in-chat card does. Elsewhere `dshViz.state` lives as long as the\n   * document.\n   */\n  savesState?: boolean\n}\n\n/** Surface a frame document is laid out for. */\nexport type FrameVariant = 'card' | 'page'\n\n/**\n * Assemble the complete srcdoc document for one visualization frame.\n * @param options - fragment, title, bridged palette, report token, surface variant, and card style.\n * @returns the HTML document string for the iframe's `srcDoc`.\n */\nexport function buildFrameDoc(options: FrameDocOptions): string {\n  const style = STYLES[options.style ?? DEFAULT_STYLE] ?? STYLES[DEFAULT_STYLE]\n  const rootVars = Object.entries({ ...options.themeVars, ...style.vars })\n    .map(([name, value]) => [name, sanitizeCssValue(value)] as const)\n    .filter(([, value]) => value.length > 0)\n    .map(([name, value]) => `--dsh-viz-${name}: ${value};`)\n    .join(' ')\n  return `<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"referrer\" content=\"no-referrer\">\n<meta http-equiv=\"Content-Security-Policy\" content=\"${FRAME_CSP}\">\n<title>${escapeHtml(options.title)}</title>\n${style.fontHref === undefined ? '' : `<link rel=\"stylesheet\" href=\"${escapeHtml(style.fontHref)}\">\\n`}<style>${FRAME_CSS}${options.variant === 'page' ? PAGE_CSS : ''}\n:root { ${rootVars} color-scheme: ${options.colorScheme}; }\n${options.variant === 'page' ? '' : 'body { padding: 4px 2px; }'}${style.extraCss === undefined ? '' : `\\n${style.extraCss}`}</style>\n<script>${vizHelperScript(style.id, style.chart, options.promptable === true ? options.reportToken : undefined, {\n    values: options.savedState,\n    token: options.savesState === true ? options.reportToken : undefined,\n  })}</script>\n</head>\n<body>\n${options.fragment}\n<script>${heightReporter(options.reportToken)}</script>\n</body>\n</html>\n`\n}\n\n/**\n * The frame-side height reporter: posts the document's scroll height to the\n * parent on load and on every resize, so the card can size the iframe to its\n * content (a sandboxed frame's document is unreachable from the parent).\n * @param reportToken - correlation token echoed in each message.\n * @returns the inline script body.\n */\nfunction heightReporter(reportToken: string): string {\n  const token = JSON.stringify(reportToken)\n  return `\n(function () {\n  var post = function () {\n    parent.postMessage({\n      type: ${JSON.stringify(HEIGHT_MESSAGE_TYPE)},\n      token: ${token},\n      height: document.documentElement.scrollHeight,\n    }, '*');\n  };\n  new ResizeObserver(post).observe(document.documentElement);\n  addEventListener('load', post);\n  post();\n})();\n`\n}\n\n/**\n * Assemble the persistent streaming shell: an initially empty document that\n * receives fragment prefixes over `postMessage` and syncs them into its DOM\n * incrementally — unchanged elements persist (no reload churn) and newly\n * arrived elements float in via an enter animation, the Claude-style\n * component-by-component reveal. Scripts inside synced markup stay inert by\n * the `innerHTML` parsing rule, which is exactly right for a half-generated\n * fragment; the settled card runs the finished scripts.\n * @param options - bridged palette, scheme, and correlation token (fragment is ignored).\n * @returns the HTML document string for the preview iframe's `srcDoc`.\n */\nexport function buildStreamShellDoc(options: Omit<FrameDocOptions, 'fragment' | 'title'>): string {\n  const shell = buildFrameDoc({\n    ...options,\n    title: 'Streaming preview',\n    fragment: `<div id=\"dsh-viz-stream-root\"></div>\n<style>\n.dsh-viz-enter { animation: dsh-viz-enter 0.4s cubic-bezier(0.2, 0.7, 0.3, 1) both; }\n@keyframes dsh-viz-enter { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }\n</style>\n<script>${streamSync(options.reportToken)}</script>`,\n  })\n  return shell\n}\n\n/**\n * The frame-side incremental DOM sync: parses each posted fragment prefix\n * into a detached tree and reconciles it against the live root by child\n * index — same tag syncs attributes and recurses, a mismatch replaces, a new\n * node appends with the enter class, extras drop. Index-based reconciliation\n * is exact for streamed markup, which only ever grows or refines its tail.\n * @param reportToken - correlation token accepted on incoming messages.\n * @returns the inline script body.\n */\nfunction streamSync(reportToken: string): string {\n  return `\n(function () {\n  var root = document.getElementById('dsh-viz-stream-root');\n  var token = ${JSON.stringify(reportToken)};\n  function syncAttrs(cur, next) {\n    var i, attrs = cur.attributes;\n    for (i = attrs.length - 1; i >= 0; i--) {\n      if (!next.hasAttribute(attrs[i].name)) cur.removeAttribute(attrs[i].name);\n    }\n    attrs = next.attributes;\n    for (i = 0; i < attrs.length; i++) {\n      if (cur.getAttribute(attrs[i].name) !== attrs[i].value) cur.setAttribute(attrs[i].name, attrs[i].value);\n    }\n  }\n  function executable(node) {\n    // Scripts parsed via innerHTML are permanently inert; an executable clone\n    // runs on insertion. Streamed markup only ever appends, so each complete\n    // script block arrives at its index exactly once and runs exactly once.\n    var script = document.createElement('script');\n    for (var i = 0; i < node.attributes.length; i++) {\n      script.setAttribute(node.attributes[i].name, node.attributes[i].value);\n    }\n    script.textContent = node.textContent;\n    return script;\n  }\n  function sync(cur, next) {\n    var want = next.childNodes, have = cur.childNodes, i;\n    for (i = 0; i < want.length; i++) {\n      var target = want[i], live = have[i];\n      if (live === undefined) {\n        var added = target.nodeName === 'SCRIPT' ? executable(target) : target.cloneNode(true);\n        if (added.nodeType === 1 && added.nodeName !== 'SCRIPT') added.classList.add('dsh-viz-enter');\n        cur.appendChild(added);\n        continue;\n      }\n      if (live.nodeType !== target.nodeType || live.nodeName !== target.nodeName) {\n        cur.replaceChild(target.cloneNode(true), live);\n        continue;\n      }\n      if (live.nodeType === 3 || live.nodeType === 8) {\n        if (live.nodeValue !== target.nodeValue) live.nodeValue = target.nodeValue;\n        continue;\n      }\n      if (live.nodeType === 1) {\n        syncAttrs(live, target);\n        sync(live, target);\n      }\n    }\n    while (cur.childNodes.length > want.length) cur.removeChild(cur.lastChild);\n  }\n  addEventListener('message', function (event) {\n    var data = event.data;\n    if (!data || data.type !== ${JSON.stringify(STREAM_MESSAGE_TYPE)} || data.token !== token) return;\n    if (typeof data.fragment !== 'string') return;\n    var next = document.createElement('div');\n    next.innerHTML = data.fragment;\n    sync(root, next);\n  });\n})();\n`\n}\n\n/**\n * Keep one bridged palette value inert inside a style block: resolved\n * computed-style colors never contain declaration or block delimiters, so any\n * occurrence marks a malformed value, dropped rather than repaired.\n * @param value - the raw computed-style value.\n * @returns the trimmed value, or empty when it must be dropped.\n */\nexport function sanitizeCssValue(value: string): string {\n  const trimmed = value.trim()\n  return /[;{}<>]/u.test(trimmed) ? '' : trimmed\n}\n\n/**\n * Minimal HTML text escape for the frame `<title>`.\n * @param text - raw text.\n * @returns the escaped text.\n */\nfunction escapeHtml(text: string): string {\n  return text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')\n}\n"
    },
    {
      "path": "src/storage.ts",
      "content": "/**\n * Where a card's settled fragment lives on disk, and how an `update` finds it\n * again.\n *\n * New cards go to a per-session store under the harness home —\n * `$DSH_HOME/visualize/sessions/<session>/<slug>-<hash>.<style>.html` — never into the\n * user's project, so `git status` stays clean and conversations do not mix.\n * The plugin owns these files and writes them with its own node fs: the store\n * sits outside every sandbox write root, and the model never addresses it\n * except by handing back a path this module reported.\n *\n * The home comes from the host's `dshHomePath` value, which app-boot provides\n * on the root context from dsh 0.1.1 onward; a host without it (or a call\n * without a session) keeps the original behaviour, a copy under `viz/` in the\n * session workspace written through `ctx.fs` and the session sandbox policy.\n *\n * An `update` path is model-supplied, so it is only trusted as far as it\n * proves itself: a path inside the store is read and rewritten with node fs;\n * a legacy `viz/...` copy from an earlier session must be an `.html` file\n * inside the session workspace, after `~` expansion, `..` normalization, and\n * symlink resolution, and goes through `ctx.fs` under the sandbox policy. Any\n * other path is refused before it is read: the sandbox confines writes, not\n * reads, and a failed patch quotes card text back to the model.\n *\n * Images a card embeds (`data-viz-src`, see images.ts) are stored beside the\n * session's cards, content-addressed under `images/`, and each store card\n * keeps a sidecar manifest (`<card>.images.json`) of what it resolved so an\n * `update` can carry them. The browser reads them back through one exact\n * route ({@link handleImageRequest}) that only ever opens a file named by a\n * well-formed id below the store root.\n *\n * @module @nagi-ovo/dsh-visualize/storage\n */\n\nimport { createHash, randomBytes } from 'node:crypto'\nimport { access, lstat, mkdir, readFile, realpath, rename, rm, writeFile } from 'node:fs/promises'\nimport { homedir } from 'node:os'\nimport { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { FsTarget } from '@deepseek-ai/dsh-fs'\nimport type {} from '@deepseek-ai/dsh-sandbox-policy'\nimport { CARD_IMAGE_TYPES, type CardImage, type CardImageType } from './fragment.ts'\n\n/** Directory under the harness home that holds every plugin-owned card. */\nexport const STORE_DIR = 'visualize'\n\n/** The host's home-path joiner: `dshHomePath(...segments)` → absolute path. */\ntype HomePath = (...segments: string[]) => string\n\n/** The slice of a tool execution the store reads. */\nexport interface CardExec {\n  readonly agent?: { readonly session: { readonly id?: unknown; readonly header: { readonly cwd?: string } } }\n  readonly signal: AbortSignal\n}\n\n/** One resolved card file: where it is, and how to read and rewrite it. */\nexport interface CardFile {\n  /** The path reported to the model and shown in the card header. */\n  readonly displayPath: string\n  read(): Promise<string>\n  write(content: string): Promise<void>\n  /** The card's image manifest; only store cards have one. */\n  readonly images?: ImageManifest\n}\n\n/** A resolved image as the manifest keeps it: the meta reference plus where it came from. */\nexport interface StoredImage extends CardImage {\n  /** `url` images are carried across patches; `file` images are re-read. */\n  origin: 'url' | 'file'\n}\n\n/** The images one store card resolved. */\nexport interface ImageManifest {\n  /** The recorded images; empty when there is no manifest or it is unreadable. */\n  read(): Promise<StoredImage[]>\n  write(images: readonly StoredImage[]): Promise<void>\n}\n\n/** Content-addressed image bytes for one session. */\nexport interface ImageStore {\n  /**\n   * Store bytes under their digest.\n   * @returns the id the image route serves.\n   */\n  put(data: Uint8Array, type: CardImageType): Promise<string>\n  /** Whether an id names stored bytes. */\n  exists(id: string): Promise<boolean>\n}\n\n/** Card files for one tool execution. */\nexport interface CardStore {\n  /** Where a new card named `name` (one safe segment) is written. */\n  create(name: string): Promise<CardFile>\n  /** The existing card a model-supplied `update` path addresses. */\n  open(path: string): Promise<CardFile>\n  /** This session's image store; absent where `create` falls back to the workspace. */\n  readonly images: ImageStore | undefined\n  /** The session workspace root, as the sandbox policy names it; undefined without one. */\n  readonly workspaceRoot: string | undefined\n}\n\n/**\n * Build the card store for one execution.\n * @param ctx - registrant context carrying `ctx.fs`, `sandboxPolicy`, and the host home path.\n * @param exec - the calling execution, for its session and signal.\n * @returns the store; its `create` falls back to the workspace when the host lacks a home path.\n */\nexport function cardStore(ctx: Context, exec: CardExec): CardStore {\n  const root = storeRoot(ctx)\n  const sessionId = exec.agent?.session.id\n  const workspace = workspaceFiles(ctx, exec)\n  return {\n    async create(name) {\n      if (root === undefined || typeof sessionId !== 'string' || sessionId.length === 0) {\n        return await workspace.open(`viz/${name}`)\n      }\n      return ownedFile(root, join(root, 'sessions', sessionSegment(sessionId), name))\n    },\n    images: root === undefined || typeof sessionId !== 'string' || sessionId.length === 0\n      ? undefined\n      : sessionImages(root, sessionSegment(sessionId)),\n    workspaceRoot: workspace.root,\n    async open(path) {\n      const owned = root === undefined ? undefined : await ownedPath(root, path)\n      if (owned !== undefined) return ownedFile(root!, owned)\n      const legacy = await workspacePath(workspace.root, path)\n      if (legacy === undefined) {\n        throw new Error(\n          `invalid visualization patch: ${JSON.stringify(path)} is not a card visualize can patch — pass the path `\n          + 'a visualize call reported (a card in the session store, or a legacy viz/ .html copy inside the workspace)',\n        )\n      }\n      return await workspace.open(legacy)\n    },\n  }\n}\n\n/**\n * Accept a model-supplied path as a legacy workspace card only if it names an\n * `.html` file inside the session workspace, lexically and after symlink\n * resolution. The fs seam's sandbox confines writes but not reads, and a\n * failed patch quotes the card text back, so an unconfined read would leak\n * any file the host can open.\n * @param root - the session workspace root, undefined when the session has none.\n * @param path - the `update` path as the model passed it (`~/` allowed).\n * @returns the path to resolve through the seam, or undefined when it is not contained.\n */\nexport async function workspacePath(root: string | undefined, path: string): Promise<string | undefined> {\n  if (root === undefined || !isAbsolute(root)) return undefined\n  const tilde = path === '~' || path.startsWith('~/')\n  const expanded = tilde ? join(homedir(), path.slice(1)) : path\n  const base = resolve(root)\n  const target = resolve(base, expanded)\n  if (!inside(base, target) || !target.endsWith('.html')) return undefined\n  const realRoot = await realpath(base).catch(() => base)\n  if (!inside(realRoot, await realpathOfDeepest(target))) return undefined\n  // A plain relative path resolves against this same root in the seam, which\n  // keeps its display form; anything else goes in as the checked absolute path.\n  return tilde || isAbsolute(path) ? target : path\n}\n\n/**\n * Resolve symlinks in the longest existing prefix of `target`; the missing\n * remainder cannot be a link yet.\n * @param target - absolute path.\n * @returns the real path of the deepest existing ancestor joined with the rest.\n */\nexport async function realpathOfDeepest(target: string): Promise<string> {\n  let existing = target\n  for (;;) {\n    try {\n      return join(await realpath(existing), relative(existing, target))\n    } catch {\n      const parent = dirname(existing)\n      if (parent === existing) return target\n      existing = parent\n    }\n  }\n}\n\n/**\n * The store root under the harness home, when the host provides one.\n * @param ctx - registrant context.\n * @returns the absolute root, or undefined on a host without `dshHomePath`.\n */\nexport function storeRoot(ctx: Context): string | undefined {\n  let homePath: unknown\n  try {\n    homePath = ctx.get('dshHomePath')\n  } catch {\n    return undefined\n  }\n  if (typeof homePath !== 'function') return undefined\n  const root = (homePath as HomePath)(STORE_DIR)\n  return typeof root === 'string' && isAbsolute(root) ? resolve(root) : undefined\n}\n\n/**\n * Encode a session id as exactly one path segment, injectively: every\n * character outside `[A-Za-z0-9_-]` — separators, dots, `~` itself — becomes\n * `~` plus its code point in hex, so no id can name `.`, `..`, or a nested path.\n * @param id - the raw session id.\n * @returns the directory name for that session.\n */\nexport function sessionSegment(id: string): string {\n  return Array.from(id, char => /^[A-Za-z0-9_-]$/u.test(char)\n    ? char\n    : `~${char.codePointAt(0)!.toString(16).padStart(4, '0')}`).join('')\n}\n\n/**\n * Accept a model-supplied path as a store file only if it names an `.html`\n * file below the root after normalization and symlink resolution.\n * @param root - absolute store root.\n * @param path - the `update` path as the model passed it (`~/` allowed).\n * @returns the absolute store path, or undefined when it is not a store file.\n */\nexport async function ownedPath(root: string, path: string): Promise<string | undefined> {\n  const expanded = path === '~' || path.startsWith('~/') ? join(homedir(), path.slice(1)) : path\n  if (!isAbsolute(expanded)) return undefined\n  const target = resolve(expanded)\n  if (!inside(root, target) || !target.endsWith('.html')) return undefined\n  // A symlink inside the store — the file or a directory above it — must not\n  // carry a read or a write anywhere else.\n  const real = await realpath(target).catch(async () => await realpath(dirname(target)).then(\n    parent => join(parent, 'card.html'),\n    () => undefined,\n  ))\n  // Nothing on disk yet: the card does not exist, and the read fails loudly.\n  if (real === undefined) return target\n  const realRoot = await realpath(root).catch(() => root)\n  return inside(realRoot, real) ? target : undefined\n}\n\n/**\n * Whether `target` lies strictly below `root`.\n * @param root - absolute directory.\n * @param target - absolute path.\n * @returns true for a descendant, false for the root itself or anything outside.\n */\nexport function inside(root: string, target: string): boolean {\n  const rel = relative(root, target)\n  return rel.length > 0 && !rel.startsWith(`..${sep}`) && rel !== '..' && !isAbsolute(rel)\n}\n\n/**\n * A plugin-owned card file, read and written with node fs. Writes go through\n * a sibling temporary file and a rename, so a reader never sees half a card.\n * @param root - absolute store root, for the display form.\n * @param path - absolute file path below the root.\n * @returns the card file.\n */\nfunction ownedFile(root: string, path: string): CardFile {\n  return {\n    displayPath: displayOf(path),\n    read: async () => await readFile(path, 'utf8'),\n    write: async content => await writeFileAtomic(path, content),\n    images: manifestAt(`${path.slice(0, -'.html'.length)}.images.json`),\n  }\n}\n\n/** Directory under a session's card directory that holds its images. */\nconst IMAGE_DIR = 'images'\n\n/** File extension each image type is stored under. */\nexport const IMAGE_EXTENSIONS: Readonly<Record<CardImageType, string>> = {\n  'image/png': 'png',\n  'image/jpeg': 'jpg',\n  'image/gif': 'gif',\n  'image/webp': 'webp',\n  'image/svg+xml': 'svg',\n}\n\n/** A well-formed image id: one session segment, a sha256 digest, a known extension. */\nconst IMAGE_ID = /^([A-Za-z0-9_~-]+)\\/([0-9a-f]{64})\\.(png|jpg|gif|webp|svg)$/u\n\n/**\n * The store path an image id names, or undefined for anything but a\n * well-formed id: no separator, dot segment, or other extension gets through.\n * @param root - absolute store root.\n * @param id - the id as a request or a manifest carries it.\n * @returns the absolute path below the root.\n */\nexport function imagePath(root: string, id: string): string | undefined {\n  const m = IMAGE_ID.exec(id)\n  return m === null ? undefined : join(root, 'sessions', m[1]!, IMAGE_DIR, `${m[2]}.${m[3]}`)\n}\n\n/**\n * One session's image store.\n * @param root - absolute store root.\n * @param segment - the session's directory name ({@link sessionSegment}).\n * @returns the store.\n */\nfunction sessionImages(root: string, segment: string): ImageStore {\n  return {\n    async put(data, type) {\n      const id = `${segment}/${createHash('sha256').update(data).digest('hex')}.${IMAGE_EXTENSIONS[type]}`\n      const path = imagePath(root, id)!\n      // Content-addressed: identical bytes are already there.\n      if (!await exists(path)) await writeFileAtomic(path, data)\n      return id\n    },\n    async exists(id) {\n      const path = imagePath(root, id)\n      return path !== undefined && await exists(path)\n    },\n  }\n}\n\n/** Whether a path exists. */\nasync function exists(path: string): Promise<boolean> {\n  return await access(path).then(() => true, () => false)\n}\n\n/**\n * A store card's sidecar manifest. Unreadable or malformed content reads as\n * empty, so a damaged manifest costs a re-resolve, never the patch.\n * @param path - absolute manifest path beside the card.\n * @returns the manifest.\n */\nfunction manifestAt(path: string): ImageManifest {\n  return {\n    async read() {\n      let parsed: unknown\n      try {\n        parsed = JSON.parse(await readFile(path, 'utf8'))\n      } catch {\n        return []\n      }\n      if (!Array.isArray(parsed)) return []\n      return parsed.flatMap((entry: Partial<StoredImage> | null) => {\n        if (typeof entry !== 'object' || entry === null) return []\n        const { src, id, type, bytes, origin } = entry\n        if (typeof src !== 'string' || typeof id !== 'string' || IMAGE_ID.exec(id) === null) return []\n        if (typeof bytes !== 'number' || !CARD_IMAGE_TYPES.includes(type!) || (origin !== 'url' && origin !== 'file')) return []\n        return [{ src, id, type: type!, bytes, origin }]\n      })\n    },\n    async write(images) {\n      if (images.length === 0) await rm(path, { force: true })\n      else await writeFileAtomic(path, JSON.stringify(images))\n    },\n  }\n}\n\n/**\n * Read one stored image for the route: the id must be well formed, the file\n * a regular file (not a symlink) whose real path stays below the store root,\n * and its bytes must still hash to the digest the id names.\n * @param root - absolute store root, undefined on a host without one.\n * @param id - the requested id.\n * @returns the bytes, or undefined when the id names nothing servable.\n */\nexport async function readStoredImage(root: string | undefined, id: string): Promise<Uint8Array | undefined> {\n  if (root === undefined) return undefined\n  const path = imagePath(root, id)\n  if (path === undefined) return undefined\n  const stat = await lstat(path).catch(() => undefined)\n  if (stat === undefined || !stat.isFile()) return undefined\n  const realRoot = await realpath(root).catch(() => root)\n  const real = await realpath(path).catch(() => undefined)\n  if (real === undefined || !inside(realRoot, real)) return undefined\n  const data = await readFile(real).catch(() => undefined)\n  if (data === undefined) return undefined\n  const digest = createHash('sha256').update(data).digest('hex')\n  return digest === IMAGE_ID.exec(id)![2] ? new Uint8Array(data.buffer, data.byteOffset, data.byteLength) : undefined\n}\n\n/**\n * Answer one request on the image route (`IMAGE_ROUTE_PATH`): `GET ?id=<image id>`. The\n * host channel has already authenticated the browser as the owner. The bytes\n * go out as an opaque download, never as a renderable type, so opening the\n * URL directly cannot run an SVG's script on the app's origin; the card\n * itself knows each image's type from its meta.\n * @param root - absolute store root, undefined on a host without one.\n * @param request - the request.\n * @returns the response.\n */\nexport async function handleImageRequest(root: string | undefined, request: Request): Promise<Response> {\n  if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('method not allowed', { status: 405 })\n  const id = new URL(request.url).searchParams.get('id') ?? ''\n  const data = await readStoredImage(root, id)\n  if (data === undefined) return new Response('not found', { status: 404, headers: { 'cache-control': 'no-store' } })\n  return new Response(request.method === 'HEAD' ? null : data as Uint8Array<ArrayBuffer>, {\n    status: 200,\n    headers: {\n      'content-type': 'application/octet-stream',\n      'content-length': String(data.byteLength),\n      'content-disposition': 'attachment',\n      'content-security-policy': \"default-src 'none'; sandbox\",\n      'x-content-type-options': 'nosniff',\n      // Content-addressed, so a cached copy can never go stale.\n      'cache-control': 'private, max-age=31536000, immutable',\n    },\n  })\n}\n\n/**\n * Write a plugin-owned file through a sibling temporary file and a rename, so\n * a reader never sees half of it. The rename replaces a symlink at `path`\n * rather than writing through it.\n * @param path - absolute file path; missing parent directories are created private.\n * @param content - the new text, or raw bytes.\n */\nexport async function writeFileAtomic(path: string, content: string | Uint8Array): Promise<void> {\n  await mkdir(dirname(path), { recursive: true, mode: 0o700 })\n  // Unique per write, not per millisecond: concurrent creates of the same\n  // content-addressed card would otherwise share one temp file, and the\n  // second rename would find it already moved. With distinct temps both\n  // renames land, and identical bytes make the last one a no-op.\n  const temp = `${path}.${process.pid}.${randomBytes(6).toString('hex')}.tmp`\n  try {\n    await writeFile(temp, content, { encoding: 'utf8', mode: 0o600, flag: 'wx' })\n    await rename(temp, path)\n  } catch (error) {\n    // EEXIST means the name was taken and the file is not ours to remove.\n    if ((error as NodeJS.ErrnoException).code !== 'EEXIST') await rm(temp, { force: true }).catch(() => {})\n    throw error\n  }\n}\n\n/**\n * Shorten an absolute store path for display: the OS home becomes `~`, which\n * {@link ownedPath} expands again when the model hands the path back.\n * @param path - absolute path.\n * @returns the display path.\n */\nfunction displayOf(path: string): string {\n  const home = homedir()\n  return path.startsWith(`${home}${sep}`) ? `~${path.slice(home.length)}` : path\n}\n\n/**\n * Workspace files through the composed fs seam and the session-level sandbox\n * policy, as the official fs tools resolve them: the calling session's cwd is\n * the workspace root. Without the session policy a confining backend falls\n * back to its process-level default root and denies the write whenever the\n * session cwd lies elsewhere.\n * @param ctx - registrant context.\n * @param exec - the calling execution.\n * @returns the workspace root (undefined when the session has none) and a\n * resolver from a workspace-relative or absolute path to a card file.\n */\nfunction workspaceFiles(ctx: Context, exec: CardExec): { root: string | undefined; open: (path: string) => Promise<CardFile> } {\n  const sandboxPolicy = ctx.get('sandboxPolicy')?.resolve({\n    ...exec.agent ? { session: exec.agent.session as never } : {},\n  })\n  const cwd = sandboxPolicy?.workspaceRoot ?? exec.agent?.session.header.cwd\n  const resolveOpts = { ...cwd !== undefined ? { cwd } : {}, signal: exec.signal }\n  return {\n    root: cwd,\n    async open(path) {\n      const target: FsTarget = await ctx.fs.resolve(path, resolveOpts)\n      return {\n        displayPath: target.displayPath,\n        read: async () => await ctx.fs.readText(target, exec.signal),\n        async write(content) {\n          await ctx.fs.writeText(target, content, undefined, exec.signal, sandboxPolicy)\n        },\n      }\n    },\n  }\n}\n"
